L3_1 = {}
L3_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 3800207
L3_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L3_1.m_Pos = "C"
L3_1.m_Talk_KOREA = "그럼 그 때 폭발이 일어난 가게에 계셨던 사장님은 괜찮으신 건가요?"
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "では、あの時爆発が起きた店にいらっしゃったオーナーは大丈夫ですか？"
L3_1.m_Talk_ENG = "Then, what about your boss, who was in the bar at the time of the explosion? Is she okay?"
L3_1.m_Talk_TWN = "那爆炸當時在店裡的老闆娘沒事嗎？"
L3_1.m_Talk_THA = "แล้ว บอสคุณล่ะคะ? คนที่อยู่ในบาร์ตอนระเบิดน่ะ เธอเป็นอะไรรึเปล่าคะ?"
L3_1.m_Talk_VTN = "Vậy còn sếp của cô, người đã ở trong quán bar vào thời điểm vụ nổ xảy ra? Cô ấy ổn chứ?"
L3_1.m_Talk_SCN = "那么当时爆炸的时候，老板在店里没事吗？"
L3_1.m_Talk_DEU = "Was ist dann mit eurer Chefin, die zum Zeitpunkt der Explosion in der Bar war? Geht es ihr gut?"
L3_1.m_Talk_FRA = "Vous m'avez bien dit que votre patronne était dans le bar au moment de l'explosion, non ? Elle a pu s'en sortir ?"
L4_1 = {}
L4_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 3800207
L4_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L4_1.m_bWaitClick = true
