L4_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L4_1.m_Pos = "C"
L4_1.m_Talk_KOREA = "으음… 니콜 양… 한잔 더~"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "ううん……ニコルちゃん……おかわり……"
L4_1.m_Talk_ENG = "Mm... Nicole... Gimme one more glass..."
L4_1.m_Talk_TWN = "嗯…妮可…再來一杯～"
L4_1.m_Talk_THA = "งืม... นิโคล... ขออีกแก้วสิ"
L4_1.m_Talk_VTN = "Mm... Nicole... Cho tôi một ly nữa nào..."
L4_1.m_Talk_SCN = "嗯……妮可小姐……再来一杯~"
L4_1.m_Talk_DEU = "Mm ... Nicole ... Gib mir noch ein Glas ..."
L4_1.m_Talk_FRA = "Mmh... Nicole... Donne-moi un autre verre..."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 3800207
L5_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_LAUGH"
L5_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L5_1.m_Pos = "C"
L5_1.m_Talk_KOREA = "보다시피 멀쩡하세요. 운이 좋으셨대요."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "ご覧の通り元気です。運が良かったそうです。"
L5_1.m_Talk_ENG = "As you can see, yes. She was lucky."
L5_1.m_Talk_TWN = "就像你看到的，老闆娘非常平安，消防員都說她很幸運。"
L5_1.m_Talk_THA = "ก็อย่างที่เห็นแหละค่ะ โชคเธอดี"
L5_1.m_Talk_VTN = "Như cô có thể thấy. Cô ấy rất may mắn."
L5_1.m_Talk_SCN = "如你所见，人没事。可能是运气好吧。"
L5_1.m_Talk_DEU = "Wie du sehen kannst, ja. Sie hatte Glück."
L5_1.m_Talk_FRA = "Comme vous pouvez le voir, oui. Elle a eu de la chance."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 3800207
L6_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_DESPAIR"
L6_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L6_1.m_Pos = "C"
L6_1.m_Talk_KOREA = "다행이네요. 범죄조직의 폭탄테러라니… 상상만 해도 끔찍해요."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "よかったですね。犯罪組織の爆弾テロだなんて……\n想像しただけでもゾッとします。"
L6_1.m_Talk_ENG = "I'm glad. Bombing by a criminal organization... *Shudder* So terrible!"
L6_1.m_Talk_TWN = "真的欸～犯罪組織的炸彈恐怖事件…光想就覺得可怕。"
L6_1.m_Talk_THA = "โล่งใจไปนะคะ โดนองค์กรอาชญากรรมวางระเบิดนี่... *ตัวสั่น* น่ากลัวมากค่ะ!"
L6_1.m_Talk_VTN = "Tôi rất vui. Bị một tổ chức tội phạm cài bom... *Rùng mình* Kinh khủng quá!"
L6_1.m_Talk_SCN = "真幸运。犯罪组织的炸弹袭击……想象下都很恐怖呢。"
L6_1.m_Talk_DEU = "Das freut mich. Eine Bombardierung durch eine kriminelle Organisation ... *schauder* Wie schrecklich!"
L6_1.m_Talk_FRA = "C'est le cas de le dire. Un attentat à la bombe perpétré par une organisation criminelle... ça fait froid dans le dos !"
L7_1 = {}
L7_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 3800207
L7_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_IDLE"
L7_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L7_1.m_Pos = "C"
L7_1.m_Talk_KOREA = "그나마 다행인 건, 덕분에 그라운드 원으로 와서 가게를 새로 차렸다는 거죠."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "不幸中の幸いなのは、おかげでグラウンド・ワンに来て新しい店をオープンできたことです。"
L7_1.m_Talk_ENG = "But because of it, we moved to Ground One and opened this new bar."
L7_1.m_Talk_TWN = "不過也因為這樣，店才能搬到G1重新開張。"
L7_1.m_Talk_THA = "แต่ก็เพราะแบบนั้นนะคะ เราเลยได้ย้ายมาเปิดบาร์ใหม่ที่กราวด์วัน"
L7_1.m_Talk_VTN = "Nhưng vì nó, chúng tôi đã chuyển đến Ground One và mở quán bar mới này."
L7_1.m_Talk_SCN = "不幸中的万幸就是可以因此来G1新开一家店。"
L7_1.m_Talk_DEU = "Aber dank dessen sind wir ja ins Ground One gezogen und haben diese neue Bar eröffnet."
L7_1.m_Talk_FRA = "Mais dans notre malheur, nous avons quand même de la chance. Grâce à ça, nous avons pu ouvrir ce nouveau bar au Site n°1."
L8_1 = {}
L8_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 3800207
L8_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L8_1.m_Pos = "C"
L8_1.m_Talk_KOREA = "이전 동네는 범죄자들 놀이터라고 해도 과언이 아니었거든요."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "以前の町は犯罪者のたまり場と言っても過言ではない場所でしたので。"
L8_1.m_Talk_ENG = "The previous neighborhood we were in was practically a playground for criminals."
L8_1.m_Talk_TWN = "之前那個地方，說是犯罪者的天堂根本也不為過。"
L8_1.m_Talk_THA = "แถวที่เดิมที่เราอยู่นี่อย่างกับสนามเด็กเล่นของอาชญากร"
L8_1.m_Talk_VTN = "Khu phố trước đây chúng tôi ở thực tế là chỗ bọn tội phạm tác oai tác quái."
L8_1.m_Talk_SCN = "以前那家店附近，毫不夸张地说是罪犯们的乐园。"
L8_1.m_Talk_DEU = "Die alte Nachbarschaft, in der wir waren, war praktisch ein Spielplatz für Kriminelle."
L8_1.m_Talk_FRA = "C'est quand même autre chose que le repaire de criminels où nous étions avant..."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 3800207
L9_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_IDLE"
L9_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L9_1.m_Pos = "C"
L9_1.m_Talk_KOREA = "그 점에 대해선 걱정 마세요."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "その点については心配いりません。"
L9_1.m_Talk_ENG = "You don't have to worry about that here."
L9_1.m_Talk_TWN = "這點你大可以放心！"
L9_1.m_Talk_THA = "อยู่นี่ไม่ต้องห่วงเรื่องนั้นนะคะ"
L9_1.m_Talk_VTN = "Cô không cần phải lo lắng về điều đó ở đây."
L9_1.m_Talk_SCN = "治安方面你不必担心。"
L9_1.m_Talk_DEU = "Hier müsst ihr euch darüber keine Gedanken machen."
L9_1.m_Talk_FRA = "Sur ce point, vous n'avez aucun souci à vous faire."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 3800207
L10_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_PRIDE"
L10_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L10_1.m_Pos = "C"
L10_1.m_Talk_KOREA = "여기 그라운드 원은 대균열의 근원지라는 이유로 아직 위험하단 인식이 남아 있지만……."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "ここグラウンド・ワンは大亀裂の根源地という理由で\nまだ危険だという認識が残っていますが……"
L10_1.m_Talk_ENG = "People think Ground One is dangerous because it's built on a Grand Dimension Crevice,"
L10_1.m_Talk_TWN = "Ｇ1這裡雖然是大峽谷的發生地點，所以大家對這裡的印象還是覺得有點危險……"
L10_1.m_Talk_THA = "ใครๆ ก็นึกว่ากราวด์วันอันตรายเพราะสร้างอยู่บนรอยแยกมิติขนาดมหึมา"
L10_1.m_Talk_VTN = "Mọi người nghĩ Ground One nguy hiểm vì nó được xây dựng trên Khe Nứt Không Gian Vĩ Đại,"
L10_1.m_Talk_SCN = "虽然因为G1是大裂谷的源头，所以大家都认为比较危险……"
L10_1.m_Talk_DEU = "Die Leute denken, dass Ground One gefährlich wäre, weil es auf einer Dimensionskluft gebaut wurde,"
L10_1.m_Talk_FRA = "Les gens pensent à tort que le Site n°1 est dangereux parce qu'il a été construit sur une crevasse de grande dimension..."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 3800207
L11_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L11_1.m_Pos = "C"
L11_1.m_Talk_KOREA = "태스크포스도 많이 모여 있고, 관리국 직할 도시인 만큼 치안 유지는 확실하니까요."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "タスクフォースカンパニーもたくさん集まっていますし、\n管理局直轄都市だけに治安維持はしっかりしてますからね。"
L11_1.m_Talk_ENG = "but a lot of TASKFORCE companies are based here, not to mention it's an Administration Direct Control City, which means it's safe."
L11_1.m_Talk_TWN = "不過這裡有聚集許多的特遣勢力，而且又是管理局直轄市，治安還算是滿好的！"
L11_1.m_Talk_THA = "แต่ทาสก์ฟอร์สตั้งอยู่ที่นี่กันหลายบริษัทเลยค่ะ ไหนจะเมืองในปกครองขององค์การบริหารโลก ซึ่งแปลว่าที่นี่ปลอดภัย"
L11_1.m_Talk_VTN = "nhưng rất nhiều công ty TASKFORCE có trụ sở tại đây, chưa kể còn có cả Thành Phố Kiểm Soát Quản Trị Trực Tiếp, có nghĩa là nó an toàn."
L11_1.m_Talk_SCN = "但因此也有很多特遣势力驻扎，作为管理局直辖城市，治安方面完全不必担心。"
L11_1.m_Talk_DEU = "aber viele TASKFORCE-Firmen haben hier ihren Sitz, ganz zu schweigen davon, dass es sich um eine Stadt der Administration handelt, was bedeutet, dass es sicher ist."
L11_1.m_Talk_FRA = "Mais les TASKFORCES sont nombreuses ici, sans oublier que la ville est placée sous le contrôle direct de l'Administration. L'endroit ne pourrait pas être plus sûr."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 3800207
L12_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L12_1.m_Pos = "C"
L12_1.m_Talk_KOREA = "정말 그런 것 같아요."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "本当にそうだと思います。"
L12_1.m_Talk_ENG = "I think you're right."
L12_1.m_Talk_TWN = "好像是欸！"
L12_1.m_Talk_THA = "น่าจะจริงของคุณนะคะ"
L12_1.m_Talk_VTN = "Hình như đúng là vậy."
L12_1.m_Talk_SCN = "好像真的是这样。"
L12_1.m_Talk_DEU = "Ich glaube auch."
L12_1.m_Talk_FRA = "Je suppose que vous avez raison, oui."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 3800207
L13_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_LAUGH"
L13_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L13_1.m_Pos = "C"
L13_1.m_Talk_KOREA = "여기서 지내는 동안 누가 칼로 협박을 당하거나 납치되는 일은 아직 한 번도 없었거든요."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "ここで暮らし始めてから、誰かがナイフで脅されたり攫われたりすることが\nまだ一度もありませんし。"
L13_1.m_Talk_ENG = "Since I came here, I've never seen anyone being mugged at knifepoint or kidnapped."
L13_1.m_Talk_TWN = "我們搬來這裡後，都還沒發生過有人亮刀威脅，或是綁架擄人的事。"
L13_1.m_Talk_THA = "ตั้งแต่มาถึง ฉันยังไม่เจอการจี้ชิงทรัพย์หรือลักพาตัวเลย"
L13_1.m_Talk_VTN = "Kể từ khi tôi đến đây, tôi chưa bao giờ thấy ai bị đâm hay bị bắt cóc cả."
L13_1.m_Talk_SCN = "因为我在这里，从来没见过有人被持刀威胁或者被绑架。"
L13_1.m_Talk_DEU = "Seitdem ich hier bin, habe ich noch nie erlebt, dass jemand mit einem Messer überfallen oder entführt wurde."
L13_1.m_Talk_FRA = "Depuis notre arrivée, je n'ai été témoin d'aucune agression. Aucune menace, aucun couteau, aucun enlèvement..."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "GREMORY_ACT2_EPILOGUE@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 3800207
L14_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L14_1.m_bWaitClick = true
