L22_1.m_Talk_KOREA = "어머, 귀여운 꼬마네요. 사장님 친척분인가 봐요."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "あら、可愛らしいおチビちゃんですね。社長の親戚の方ですか？"
L22_1.m_Talk_ENG = "Oh, who's this cute little girl? Is she your boss's relative?"
L22_1.m_Talk_TWN = "哇～好可愛的小朋友，是老闆娘的親戚嗎？"
L22_1.m_Talk_THA = "ตายแล้ว หนูน้อยน่ารักนี่ใครคะเนี่ย? ญาติบอสคุณเหรอคะ?"
L22_1.m_Talk_VTN = "Ôi, bé gái dễ thương này là ai vậy? Cô ấy là họ hàng của sếp cô à?"
L22_1.m_Talk_SCN = "哎呀。好可爱的孩子。是老板的亲戚吗？"
L22_1.m_Talk_DEU = "Oh, wer ist dieses süße kleine Mädchen? Ist sie die Verwandte Ihrer Chefin?"
L22_1.m_Talk_FRA = "Oh, regardez-moi ce petit bout de chou ! Tu es la fille de la patronne ?"
