L30_1 = "รสมันไม่เหมือนกล้วยซะทีเดียว แต่อร่อยกว่าอีก!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nó không thực sự có vị giống như chuối, nhưng nó thậm chí còn ngon hơn nhiều!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "虽然不是香蕉，但比香蕉更美味！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Es schmeckt nicht wirklich nach Banane, aber es ist noch leckerer!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Ça n'a pas du tout le goût de banane, mais c'est ce qui le rend encore meilleur !"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "GREMORY_ACT2_EPILOGUE@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 30
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3800207
L30_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
