L30_1.m_Face = "UNIT_LAUGH"
L30_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L30_1.m_Pos = "R"
L31_1 = "처음 먹어 보는구나. 좋아해서 다행이다."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "はじめて飲んだのね。喜んでくれてよかった。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "So, you've never had it before, have you? I'm glad you like it."
L30_1.m_Talk_ENG = L31_1
L31_1 = "你是第一次喝到嗎？喜歡就好～"
L30_1.m_Talk_TWN = L31_1
L31_1 = "หนูไม่เคยกินมาก่อนใช่มั้ยจ๊ะ? ดีใจจังที่ชอบ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Vậy là em chưa bao giờ uống nó hở? Em thích là được rồi."
L30_1.m_Talk_VTN = L31_1
L31_1 = "原来你是第一次品尝。还好你喜欢。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Kennst du das noch gar nicht? Ich freue mich, dass sie dir schmeckt."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Où, tu n'avais jamais goûté ? Contente que ça te plaise."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "GREMORY_ACT2_EPILOGUE@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3800207
L31_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "MOMO_BAR_NULL_NULL"
L31_1.m_Pos = "L"
L32_1 = "좋다, 인간! 너도 특별히 이 몸의 하수인으로 삼아 주마!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "よし、人間！　お前も特別に吾輩の下僕にしてやる！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Alright, human. I hereby accept you as my special subject."
L31_1.m_Talk_ENG = L32_1
L32_1 = "很好！本王就特別收你為手下吧！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เอาล่ะมนุษย์ เช่นนั้นแล้วข้าขอยอมรับเจ้าเป็นบริวารคนพิเศษ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Được rồi, con người. Ta sẽ chấp nhận cô là thần dân đặc biệt của ta."
L31_1.m_Talk_VTN = L32_1
L32_1 = "很好，人类！就特别允许你成为本尊的仆从吧！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Okay, Mensch. Hiermit akzeptiere ich dich als mein Untertan."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Bien, humaine. Pour cette offrande, j'accepte de faire de toi ma servante."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "GREMORY_ACT2_EPILOGUE@32#Talk"
