L33_1 = {}
L34_1 = 3
L35_1 = 0.15
L33_1[1] = L34_1
L33_1[2] = L35_1
L32_1.m_Bounce = L33_1
L33_1 = "매일 이곳에 와서 바나나 우유를 바치도록 하라!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "毎日ここに来てバナナジュースを捧げるがよい！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Now, you may come here every day with this banana milk for me."
L32_1.m_Talk_ENG = L33_1
L33_1 = "你每天都要來向本王獻上巧克力牛奶！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "จากนี้ เจ้าต้องเอานมรสกล้วยนี่มาให้ข้าทุกวัน"
L32_1.m_Talk_THA = L33_1
L33_1 = "Bây giờ, cô có thể đến đây mỗi ngày và đem món sữa chuối này cho ta."
L32_1.m_Talk_VTN = L33_1
L33_1 = "你要每天来这里献上香蕉牛奶！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Jetzt kannst du mir jeden Tag Bananenmilch bringen."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Désormais, tu devras venir ici tous les jours pour m'apporter un lait à la banane."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "GREMORY_ACT2_EPILOGUE@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3800207
L33_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L33_1.m_Pos = "R"
L34_1 = "그럴까? 분위기도 마음에 들고 우리 회사랑 이웃이기도 하니까……."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "そうしようかな？　雰囲気も気に入ったし、うちの会社とお隣さん同士だし……"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Sure. I like your bar's atmosphere, and it's right next to my company, too."
L33_1.m_Talk_ENG = L34_1
L34_1 = "是喔？這邊的氣氛是滿好的，又在我們公司隔壁而已……"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ได้สิคะ ฉันชอบบรรยากาศบาร์นี่ แถมอยู่ข้างบริษัทพอดีอีก"
L33_1.m_Talk_THA = L34_1
L34_1 = "Được thôi. Chị thích bầu không khí của quán bar này và nó cũng nằm ngay cạnh công ty của chị nữa."
L33_1.m_Talk_VTN = L34_1
L34_1 = "这样吗？我很喜欢这里的氛围，而且离公司也很近……"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ja, warum nicht? Ich mag die Atmosphäre dieser Bar, und sie ist auch direkt neben meiner Firma."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Aucun problème. J'aime bien l'ambiance ici, et puis c'est juste à côté de là où je travaille."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "GREMORY_ACT2_EPILOGUE@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3800207
