L34_1.m_Face = "UNIT_DESPAIR"
L34_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L34_1.m_Pos = "R"
L35_1 = "음… 하지만 술은 줄이기로 결심했는데……."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "うーん……でもお酒は控えると決心したのに……"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Mm... But I promised myself to cut down on drinking..."
L34_1.m_Talk_ENG = L35_1
L35_1 = "可是…我才想說要少喝點酒……"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เอ... แต่นั่นก็หมายความว่าฉันจะเลิกดื่มอย่างที่สัญญากับตัวเองไว้ไม่ได้นะสิคะเนี่ย"
L34_1.m_Talk_THA = L35_1
L35_1 = "Mm... Nhưng điều đó cũng có nghĩa là tôi không thể cai rượu được..."
L34_1.m_Talk_VTN = L35_1
L35_1 = "嗯……但是我好不容易下定决心戒酒……"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Mm ... aber ich hatte mir vorgenommen, weniger zu trinken ..."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Par contre, je m'étais promise de réduire ma consommation d'alcool..."
L34_1.m_Talk_FRA = L35_1
