L36_1.m_Bounce = L37_1
L37_1 = "손님~ 여기 저희 바의 인기 칵테일, 벨벳 블로섬입니다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "お待たせしました。こちらのバーの人気カクテル、ベルベットブロッサムです。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Here's one of our favorite cocktails, the Velvet Blossom."
L36_1.m_Talk_ENG = L37_1
L37_1 = "小姐～這是我們店的招牌 紅絲絨花雞尾酒。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "นี่เป็นค็อกเทลที่เราชอบที่สุดตัวหนึ่ง เวลเว็ตบลอสซัมค่ะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Đây là một trong những loại cocktail được yêu thích nhất của chúng tôi, Hoa Nhung."
L36_1.m_Talk_VTN = L37_1
L37_1 = "顾客~这是我们酒吧最有人气的鸡尾酒，天鹅绒花。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Bitte sehr, einer unserer Lieblingscocktails, der Velvet Blossom."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Et voici un de nos cocktails signature, le Velvet Blossom."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "GREMORY_ACT2_EPILOGUE@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3800207
L37_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L37_1.m_bWaitClick = true
