L37_1.m_Face = "UNIT_LAUGH"
L37_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "앞으로도 자주 뵐 것 같으니, 첫 잔은 서비스로 드릴게요!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "これからもよくお会いすると思いますので、一杯目はサービスしますね！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Since I have a feeling that you'll be here often, your first drink is on us."
L37_1.m_Talk_ENG = L38_1
L38_1 = "第一杯由本店招待！希望以後常來喔～"
L37_1.m_Talk_TWN = L38_1
L38_1 = "และเพราะฉันรู้สึกว่าคุณคงจะมาบ่อยๆ แก้วแรกนี้เราเลี้ยงเองนะคะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi có cảm giác rằng cô sẽ thường xuyên ghé qua, nên ly đầu tiên này chúng tôi mời."
L37_1.m_Talk_VTN = L38_1
L38_1 = "我想以后我们会经常见面的，所以第一杯我请！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Da ich das Gefühl habe, dass du oft hier sein wirst, geht der erste Drink aufs Haus."
L37_1.m_Talk_DEU = L38_1
L38_1 = "J'ai l'impression qu'on vous reverra souvent par ici, alors le premier verre est offert par la maison !"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "GREMORY_ACT2_EPILOGUE@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3800207
L38_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
