L39_1 = "FX_CUTSCEN_SHAKING_COCK"
L38_1.m_StartFXSoundName = L39_1
L38_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "와아, 예쁜 칵테일이네요! 고맙습니다!"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "わあ、きれいなカクテルですね！　ありがとうございます！"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Ooo, it looks so pretty! Thank you!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "哇～好美的雞尾酒！謝謝！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "โหหห สวยจัง! ขอบคุณนะคะ!"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ooo, nó trông đẹp thế! Cảm ơn!"
L38_1.m_Talk_VTN = L39_1
L39_1 = "哇啊，好漂亮的鸡尾酒！谢谢！"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ui, das sieht so hübsch aus! Danke schön!"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Oh, il est si joli ! Merci !"
L38_1.m_Talk_FRA = L39_1
