L44_1 = "그러니까아… 내가 왜 남자들한테 인기가 없다는 건데에에~"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "だからぁ……私はどうして男からモテないのよぉ～"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Sooo... why don't men like meee?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "你說說看…為什麼我不是男生的菜～"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แล้วววว... ทามมายหนุ่มไม่ชอบช้านนนน?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Vậyyyy...tại sao đàn ông không thích tôiiiii?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "所以……我为什么不受男人欢迎呢~"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Alsooo ... warum mögen Männer mich nicht?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Snif... Pourquoi est-ce qu'aucun homme ne m'aime ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "GREMORY_ACT2_EPILOGUE@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3800207
L44_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_SERIOUS2"
L44_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "나처럼 조신하고 착한 여자가 어딨다고… 우이씨…"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "私みたいな慎ましくて優しい女なんてどこにもいないよぉ？　んもー……"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I'm a good, kind womaaaan... Sheeeshhh..."
L44_1.m_Talk_ENG = L45_1
L45_1 = "像我這麼好的女生上哪找…可惡…"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ฉันทั้งสวยทั้งใจดีเลยน้าาาา... เชอะะะะะะ...."
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi là một nười pụ nữữữữ... tốt bụng, tử tế ... Sheeeshhh..."
L44_1.m_Talk_VTN = L45_1
L45_1 = "像我这样的淑女，打着灯笼都难找……可恶……"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ich bin doch so eine gute, liebe Frau ... Hmmmpf ..."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Je suis douce et gentille... j'ai tout ce qu'il faut, pourtant ! Hic !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "GREMORY_ACT2_EPILOGUE@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3800207
L45_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_IDLE"
L45_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L45_1.m_Pos = "R"
L46_1 = "m_bCharPinup"
L45_1[L46_1] = true
L46_1 = "m_bCharPinupEasingTime"
L47_1 = 0.3
L45_1[L46_1] = L47_1
L46_1 = "(우와, 금방 취하셨네요. 성격이 점점 바뀌고 있는 것 같은데…)"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "(うわあ、すぐ酔ってしまいましたね。性格がだんだん変わってきてますが……)"
L45_1.m_Talk_JPN = L46_1
L46_1 = "(Whoa, she got drunk really quickly! And now, her personality is changing...)"
L45_1.m_Talk_ENG = L46_1
L46_1 = "(哇，這麼快就醉啦？酒品好像不太好欸…)"
L45_1.m_Talk_TWN = L46_1
L46_1 = "(เหวอ เมาไวสายฟ้าแลบมากๆ! แถมนิสัยเปลี่ยนอีก...)"
L45_1.m_Talk_THA = L46_1
L46_1 = "(Chà, cô ấy xỉn nhanh quá! Và bây giờ, tính cách của cô ấy cũng thay đổi nữa...)"
L45_1.m_Talk_VTN = L46_1
L46_1 = "（呜哇，这么快就醉了。好像性格也逐渐发生了变化……）"
L45_1.m_Talk_SCN = L46_1
L46_1 = "(Wow, sie wurde sehr schnell betrunken! Und jetzt ändert sich ihre Persönlichkeit ...)"
L45_1.m_Talk_DEU = L46_1
L46_1 = "(Wow, elle est complètement rincée ! On dirait quelqu'un d'autre...)"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "GREMORY_ACT2_EPILOGUE@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3800207
L46_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_PRIDE"
L46_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L46_1.m_Pos = "R"
L47_1 = "m_bCharPinup"
L46_1[L47_1] = true
L47_1 = "(좋아! 이럴 때일수록 당황하지 말고! 배운 대로 손님의 기분에 공감해드리자고요!)"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "(よし！　こういう時こそ慌てず！\n教わったとおりにお客様の気分に共感しましょう！)"
L46_1.m_Talk_JPN = L47_1
L47_1 = "(Alright! Stay calm, Nicole! You know what to do to build rapport with your customers!)"
L46_1.m_Talk_ENG = L47_1
L47_1 = "(不怕！這種時候千萬不能慌！就照之前學的，要附和對方！)"
L46_1.m_Talk_TWN = L47_1
L47_1 = "(เอาล่ะ! เย็นไว้นิโคล! เธอสร้างสัมพันธ์กับลูกค้าเป็นอยู่แล้วนี่!)"
L46_1.m_Talk_THA = L47_1
L47_1 = "(Được rồi! Hãy bình tĩnh, Nicole! Cô biết phải làm gì để xây dựng mối quan hệ với khách hàng mà!)"
L46_1.m_Talk_VTN = L47_1
L47_1 = "（很好！越是这种时候越不能惊慌！就像学习过的那样，尽量与顾客们的心情产生共鸣！）"
L46_1.m_Talk_SCN = L47_1
L47_1 = "(Also gut! Bleib ruhig, Nicole! Du weißt, was zu tun ist, um eine Beziehung zu deinen Gästen aufzubauen!)"
L46_1.m_Talk_DEU = L47_1
L47_1 = "(Reste calme, Nicole ! Tu sais ce qu'il faut faire dans ces cas-là !)"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
