L49_1 = "GREMORY_ACT2_EPILOGUE@48#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3800207
L48_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_LAUGH"
L48_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L48_1.m_Pos = "C"
L49_1 = "그러게요. 정말 이상하네요. 하나 씨 같은 미인이 매번 퇴짜를 맞다니."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そうですね。本当におかしいですね。\nスズカさんのような美人が毎回振られるなんて。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "That's right. That really doesn't make sense. Why would such a beautiful woman like you get dumped after just one date?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "對啊，超奇怪的，像你這麼好的女生，怎麼都沒男生看上你呢？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "นั่นสิคะ ดูไม่เข้าท่าเลย ทำไมสาวสวยอย่างคุณไปเดททีเดียวก็โดนเทซะแล้ว?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Đúng rồi. Điều đó thật vô lý. Tại sao một người phụ nữ xinh đẹp như cô lại bị đá chỉ sau một buổi hẹn hò cơ chứ?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "是啊。真是好奇怪。像千夜小姐这样的美人竟然会不受欢迎。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Stimmt. Das macht keinen Sinn. Warum wird eine so schöne Frau wie du immer nach nur einem Date abserviert?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Vous avez raison, ça n'a aucun sens. Pourquoi une aussi belle femme que vous se ferait larguer dès le premier rendez-vous ?"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "GREMORY_ACT2_EPILOGUE@49#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3800207
L49_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L49_1.m_Pos = "C"
L50_1 = "그렇게 소개팅을 많이 했는데 제대로 된 남자 하나 못 만난다는 게 말이나 되는 소린가요?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "そんなに合コンをたくさんしたのに、\nまともな男に出会えないなんてあんまりですよ！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "You've been on so many blind dates, and yet you haven't met anyone you like. That's not right, is it?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "參加過這麼多場的聯誼，竟然都沒有成功交往過，這合理嗎？！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "คุณไปนัดบอดมาก็ตั้งหลายครั้งแต่ก็ยังไม่เจอคนที่ชอบ มันดูไม่ถูกต้องเลยนะคะ เนอะ?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Cô đã đi xem mắt quá nhiều mà vẫn chưa gặp được ai cô thích. Chẳng hợp lý chút nào, phải không?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "相亲那么多次却还没遇到不错的男人，真的太奇怪了吧？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Du warst auf so vielen Blind Dates und hast noch nie einen vernünftigen Mann kennengelernt. Wie kann das nur sein?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Avec tous ces blind dates, vous n'avez toujours pas trouvé la personne qui vous convient ? Franchement, je refuse d'y croire !"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
