L6_1 = "지금껏 얼마나 많이 노력해 왔는데! 하나 씨에게 맞는 짝이 한 명도 없다니! 세상은 부조리함으로 가득한 게 틀림없어요!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "今までどれだけ努力してきたか！　スズカさんに相応しい相手が一人もいないなんて！\nこの世界は不条理に満ちているに違いありません！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "You've been trying so hard to find the man of your dreams, in vain! This world is full of injustice and unfairness!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "你這麼努力認真！怎麼會都遇不到對的人呢？這世界真的是太不公平！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "คุณพยายามหาชายในฝันแทบตายแต่ก็ยังนก! โลกนี้อะไรๆ ก็ไม่ยุติธรรมแล้วก็ไม่แฟร์เลยนะคะ!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Cô đã cố gắng rất nhiều để tìm kiếm chàng trai trong mơ, thế mà vẫn công cốc! Thế giới này toàn là bất công và bất công!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "你一直这么努力，却没遇到梦寐以求的白马王子！这个世界确实充满了不公平！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Du hast es so sehr versucht, den Mann deiner Träume zu finden, doch vergebens! Diese Welt ist voller Ungerechtigkeiten!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Tous ces efforts pour trouver l'homme de vos rêves, en vain ? Quel monde misérable... Ces injustices ne resteront pas impunies !"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
