L8_1[L9_1] = L10_1
L9_1 = "(어라? 왜 점점 악화되는 거 같죠? 이럴 땐 같이 울어드려야 하나?)"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "(あれ？　どうして悪化し続けるのでしょう？\nこういう時は一緒に泣いたほうがいいのでしょうか？)"
L8_1.m_Talk_JPN = L9_1
L9_1 = "(Err, why is she getting worse? Should I... cry with her?)"
L8_1.m_Talk_ENG = L9_1
L9_1 = "(哇咧？怎麼好像反而哭得更慘？這種時候是要陪她一起哭嗎？)"
L8_1.m_Talk_TWN = L9_1
L9_1 = "(เอ๋ ทำไมหนักขึ้นล่ะ? หรือฉัน... ควรร้องตามไปด้วยมั้ยนะ?)"
L8_1.m_Talk_THA = L9_1
L9_1 = "(Ơ, tại sao cô ấy lại khóc dữ hơn vậy? Mình có nên... khóc với cô ấy không?)"
L8_1.m_Talk_VTN = L9_1
L9_1 = "（咦？为什么感觉更加严重了？这种时候要陪她一起哭吗？）"
L8_1.m_Talk_SCN = L9_1
L9_1 = "(Ähem, warum geht es ihr immer schlechter? Soll ich ... mit ihr weinen?)"
L8_1.m_Talk_DEU = L9_1
L9_1 = "(Hein ? On dirait que son état empire... Est-ce que je dois pleurer avec elle ?)"
L8_1.m_Talk_FRA = L9_1
