L12_1 = "니콜 양, 여기서부터는 내가 맡을게."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ニコルちゃん、ここからはアタシが代わるわ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Nicole, I'll take things from here."
L11_1.m_Talk_ENG = L12_1
L12_1 = "妮可，接下來就交給我吧。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "นิโคล เดี๋ยวฉันจัดการเอง"
L11_1.m_Talk_THA = L12_1
L12_1 = "Nicole, chị sẽ xử lý cho."
L11_1.m_Talk_VTN = L12_1
L12_1 = "妮可小姐，现在这里交给我吧。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Nicole, ich übernehme ab hier."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Nicole. Je vais prendre le relais, d'accord ?"
L11_1.m_Talk_FRA = L12_1
