L13_1 = "네? 그런… 혹시 제가 무슨 실수를 한 건가요?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "はい？　そんな……もしかして私が何かやらかしましたか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Sorry? Erm, did I do something wrong?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "嗯？請問…我有哪裡做錯嗎？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "คะ? เอ๋ ฉันทำอะไรผิดไปรึเปล่าคะ?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Hic? Em đã làm gì sai sao?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "啊？是我……犯了什么错误吗？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Wie? Ähem, habe ich etwas falsch gemacht?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Pardon ? Ah... J'ai dit quelque chose qui ne fallait pas ?"
L12_1.m_Talk_FRA = L13_1
