L15_1 = "GREMORY_ACT2_EPILOGUE@64#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 64
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3800207
L14_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_IDLE"
L14_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L14_1.m_Pos = "L"
L15_1 = "하지만 취한 사람에겐 단순한 공감보다 더 직설적인 화법이 필요할 때도 있거든."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "でも、酔った人には単純な共感より、もっとストレートな話術が必要な時もあるの。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "But sometimes straightforwardness works better than empathy where drunk people are concerned."
L14_1.m_Talk_ENG = L15_1
L15_1 = "只是對於喝醉的人來說，比起單純地附和，有時候也需要更直接的表達。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "แต่บางครั้ง กับคนเมา เราพูดตรงๆ ไปเลยก็ดีกว่ามาเห็นอกเห็นใจกันนะ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Nhưng đôi khi sự thẳng thắn tốt hơn là sự đồng cảm đối với những cô nàng say xỉn."
L14_1.m_Talk_VTN = L15_1
L15_1 = "但对喝醉的人来说，有时候比起单纯的共情，不如用更加直接的聊天方式。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Aber manchmal funktioniert Geradlinigkeit besser als Empathie, wenn man mit betrunkenen Menschen redet."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Mais parfois, la franchise offre un meilleur réconfort que la compassion."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
