L16_1.m_Pos = "R"
L17_1 = "그럼 부탁드리겠습니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "では、お願いします。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Okay, then I'll leave her to you."
L16_1.m_Talk_ENG = L17_1
L17_1 = "那就麻煩你囉。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "โอเคค่ะ ฝากด้วยนะคะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Được rồi, vậy em sẽ để cô ấy cho chị."
