L17_1 = "那就拜托你了。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Okay, dann überlasse ich sie dir."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Dans ce cas, je vous laisse."
