L18_1.m_Pos = "C"
L19_1 = "m_bCharPinup"
L18_1[L19_1] = true
L19_1 = "(지금까지 그레모리 씨에게 상담받은 분들은 전부 만족하며 돌아가셨으니까요.)"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "(今までグレモリーさんに相談された方は、\nみんな満足してお帰りになりましたからね。)"
L18_1.m_Talk_JPN = L19_1
L19_1 = "(So far, everyone who talked to Gremory went home happily.)"
L18_1.m_Talk_ENG = L19_1
L19_1 = "(目前葛茉莉接待過的客人，每一個都是心滿意足地離開的。)"
L18_1.m_Talk_TWN = L19_1
L19_1 = "(ใครๆ คุยกับเกรมอรีก็กลับบ้านไปอย่างแฮปปี้ทั้งนั้น)"
L18_1.m_Talk_THA = L19_1
L19_1 = "(Cho đến giờ, tất cả những ai nói chuyện với Gremory đều vui vẻ trở về nhà.)"
L18_1.m_Talk_VTN = L19_1
L19_1 = "（至今为止向葛茉莉小姐倾诉过烦恼的人，回去时就没有看起来不开心的。）"
L18_1.m_Talk_SCN = L19_1
L19_1 = "(Bisher sind alle, die mit Gremory gesprochen haben, glücklich nach Hause gegangen.)"
L18_1.m_Talk_DEU = L19_1
L19_1 = "(Jusqu'à présent, tous les clients qui ont parlé à Gremory sont rentrés chez eux heureux.)"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
