L20_1 = "하나 양? 혹시 자기가 남자를 보는 눈이 너무 높다고 생각한 적은 없어?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "スズカちゃんは、自分が男を見る目が高すぎると思ったことはない？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Hana, don't you ever think that your standards for men are too high?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "荷娜？你有沒有想過，或許是你挑男人的眼光太高？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ฮานาคะ เป็นไปได้มั้ยคะว่ามาตรฐานด้านผู้ชายคุณอาจจะสูงไป?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Hana, có thể là do tiêu chuẩn về đàn ông của cô quá cao chăng?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "千夜小姐？难到你没想过，是你对男人的眼光太高了吗？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Hana, findest du nicht, dass deine Ansprüche an Männer zu hoch sind?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Hana. Ne t'es-tu jamais demandée si tu n'avais pas des standards un peu trop élevés ?"
L19_1.m_Talk_FRA = L20_1
