L25_1 = "GREMORY_ACT2_EPILOGUE@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3800207
L24_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_SERIOUS2"
L24_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L24_1.m_Pos = "C"
L25_1 = "흑… 제가 너무 많은 걸 바라는 걸까요? 우리 회사 사람들 정도만 돼도 좋은데…"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "ぐすん……私があまりにもハードルを高くしているんですかね？\nうちの会社の人程度でいいのに……"
L24_1.m_Talk_JPN = L25_1
L25_1 = "*Sniffle...* You think I expect too much from them? But I just want someone who's as good as my coworkers..."
L24_1.m_Talk_ENG = L25_1
L25_1 = "嗚…是我要求太多嗎？只要有我們公司員工的水準就可以啦…"
L24_1.m_Talk_TWN = L25_1
L25_1 = "*ฮึกฮึก...* คุณว่าฉันคาดหวังจากพวกเขามากไปเหรอคะ? แต่ฉันแค่อยากได้คนที่ดีเท่าพวกเพื่อนร่วมงานฉันเองนะคะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "*Hức hức ...* Cô nghĩ là tôi kỳ vọng quá nhiều ở họ? Nhưng tôi chỉ muốn ai đó tốt bụng như đồng nghiệp của tôi thôi mà..."
L24_1.m_Talk_VTN = L25_1
L25_1 = "呃……难道是我要求太高了？只要达到我们公司同事们的程度也好啊……"
L24_1.m_Talk_SCN = L25_1
L25_1 = "*Hick* Glaubst du, ich erwarte zu viel von ihnen? Aber ich will nur jemanden, der so gut ist wie meine Kollegen ..."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Snif... Vous pensez que j'en demande trop ? Mais la seule chose que j'attends d'un homme, c'est qu'il soit aussi bon que mes collègues..."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "GREMORY_ACT2_EPILOGUE@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3800207
L25_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_LAUGH"
L25_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "그래? 하나 양의 회사에 있는 사람들은 어떤데? 한 사람만 떠올려 볼래?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "そう？　スズカちゃんの会社にいる人たちはどうなの？\n一人だけ思い浮かべてみて？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Do you? Okay, then how are your coworkers? Can you give me an example?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "是嗎？你公司的人如何？可以舉個例來聽聽嗎？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เหรอคะ? โอเค งั้นอธิบายให้ฉันฟังทีสิคะว่าเพื่อนร่วมงานคุณเป็นยังไง?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Vậy à? Được rồi, đồng nghiệp của cô là người thế nào? Cô có thể cho tôi một ví dụ được không?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "是吗？那千夜小姐公司里的同事都是什么样子的人呢？可以举一个例子吗？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Wirklich? Okay, wie sind deine Kollegen? Kannst du mir ein Beispiel geben?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Vraiment ? Et comment sont-ils, tes collègues ? Tu peux me donner un exemple ?"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
