L28_1 = "GREMORY_ACT2_EPILOGUE@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3800207
L27_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "얼마 전에 입사한 신입 카운터분이요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "この前入社した新入カウンターです。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "There's this Counter who recently joined my company."
L27_1.m_Talk_ENG = L28_1
L28_1 = "之前有一個新來的制裁者。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "มีเคาน์เตอร์คนนึงที่เพิ่งมาเข้าบริษัทเราค่ะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Chà, gần đây có một Counter đã đến công ty của tôi."
L27_1.m_Talk_VTN = L28_1
L28_1 = "有一位前阵子入职的新人制裁者。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Da ist dieser Counter, der kürzlich bei uns angefangen hat."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Il y a bien cette Counter qui a rejoint l'entreprise il y a peu..."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "GREMORY_ACT2_EPILOGUE@78#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 78
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3800207
L28_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L28_1.m_Pos = "C"
L29_1 = "처음엔 회사에 적응을 잘 못 하고 싸움만 잘하는 고독한 늑대 느낌이었는데…"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "最初は会社に馴染めず、\n強いけど喧嘩ばかりする孤独な狼みたいな感じだったのに……"
L28_1.m_Talk_JPN = L29_1
L29_1 = "At first, this rookie was like a lone wolf who was good at fighting, but unable to mesh with the others."
L28_1.m_Talk_ENG = L29_1
L29_1 = "雖然她的能力很好，但她一開始不適應職場生活，感覺就像孤獨的一匹狼…"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ตอนแรก เจ้าหน้าใหม่นี่ก็เป็นพวกหมาป่าเปลี่ยวฝีมือดี แต่เข้ากับใครไม่ได้เลยค่ะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ban đầu, tân binh này giống như một con sói đơn độc thiện chiến, không bao giờ chịu kết giao với những người khác."
L28_1.m_Talk_VTN = L29_1
L29_1 = "起初吧，对公司的生活还不太适应，感觉就像是只擅长打架的孤狼……"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Anfangs war der Counter wie ein einsamer Wolf, der gut kämpfen konnte, aber nicht mit den anderen warm wurde."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Au début, elle était comme une louve solitaire. Douée pour le combat, mais incapable de s'adapter à la vie en communauté..."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "GREMORY_ACT2_EPILOGUE@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3800207
L29_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L29_1.m_Pos = "C"
L30_1 = "요즘은 자주 업무에 도움을 받기도 하고, 사람들과도 친하게 지내려는 모습이 뭔가…"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "最近はよく仕事を手伝ってもらったり、\n他の人とも仲良くしようとする姿がなんだか……"
L29_1.m_Talk_JPN = L30_1
L30_1 = "But recently, this rookie has been asking others for help and trying really hard to get along with them."
L29_1.m_Talk_ENG = L30_1
L30_1 = "但她最近開始會幫忙工作上的事，也很努力地想和大家相處…"
L29_1.m_Talk_TWN = L30_1
L30_1 = "แต่มาช่วงนี้ เจ้าหน้าใหม่นี่ก็ขอให้คนอื่นช่วยนั่นนี่ แถมพยายามเข้ากับคนอื่นให้ได้มากๆ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nhưng gần đây, tân binh này đã xin người khác giúp đỡ và thực sự cố gắng để kéo gần quan hệ với họ."
L29_1.m_Talk_VTN = L30_1
L30_1 = "但是在最近的工作中，变得愿意接受别人的帮助了，也表现出尝试与其他人亲近的样子……"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Aber in letzter Zeit hat der Counter andere um Hilfe gebeten und sich sehr bemüht, mit ihnen auszukommen."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Sauf que récemment, elle a fini par nous demander de l'aide. Et depuis, elle essaye de s'entendre avec tout le monde..."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "GREMORY_ACT2_EPILOGUE@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3800207
L30_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "덩치만 큰 순한 강아지 같달까."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "体だけ大きくて、性格は穏やかな子犬みたいというか。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "That reminds me of a big, gentle dog."
L30_1.m_Talk_ENG = L31_1
L31_1 = "感覺就像一隻塊頭很大卻很溫馴的狗狗？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ทำเอาฉันนึกถึงน้องหมาน่ารักตัวโตๆ เลยค่ะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Điều đó gợi cho tôi nhớ đến một con chó to lớn, hiền lành."
L30_1.m_Talk_VTN = L31_1
L31_1 = "感觉就像是很温顺的大狗。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Das erinnert mich an einen großen, sanften Hund."
L30_1.m_Talk_DEU = L31_1
L31_1 = "... Un peu comme un gros chien, en fait."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "GREMORY_ACT2_EPILOGUE@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3800207
L31_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_PRIDE"
L31_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "알지, 알지. 원래는 차가운 줄만 알았던 남자가 보여주는 따뜻한 반전 매력! 게다가 실력까지 갖춘 카운터라면 반할 만 하지."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "わかるわ。最初は冷たいと思っていた男が見せてくれた温かい面で\n気づく意外な魅力！　しかも実力まで備えたカウンターなら惚れてもおかしくないわ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Ooo, I know what you mean. You want someone who looks cold on the outside, but has a heart of gold. If he's also a skilled Counter, phew! I'm in!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "我懂我懂，原本以為他很冷漠，但其實個性溫暖，那種反差的魅力！而且又是很有能力的制裁者，怎麼可能不喜歡他！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "อ๋อ ฉันเข้าใจแล้วค่ะ คุณอยากได้คนที่ภายนอกดูเย็นชาแต่ว่าภายในหัวใจอบอุ่นสินะคะ แถมเป็นเคาน์เตอร์มีฝีมือ ฮู้ว! ฉันเอาด้วยค่ะ!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Ồ, tôi biết cô có ý gì. Cô muốn ai đó ngoài lạnh trong ấm chứ gì. Nếu anh ta cũng là một Counter giỏi giang, phù! Tôi thích!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "我懂了！原本高冷的男生突然对你散发出温柔的气质。这样反转的魅力，再加上还是实力兼备的制裁者，我也一定会爱上的！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ui, ich weiß, was du meinst. Du willst jemanden, der nach außen hin kalt aussieht, aber ein Herz aus Gold hat. Wenn der Counter auch noch geschickt ist, dann puh! Zum Verlieben!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Je vois ce que tu veux dire. Ferme à l'extérieur et fondant à l'intérieur, n'est-ce pas ? Et si c'est un Counter en plus, alors c'est la cerise sur le gâteau !"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "GREMORY_ACT2_EPILOGUE@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3800207
L32_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_IDLE"
L32_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "신입이라면 불러내는 것도 어렵지 않겠다. 이참에 확 고백해 버리는 건 어때?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "新人なら呼び出すのも難しくないんじゃない。\nこれを機に思い切って告白しちゃうのはどう？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "If he's new to your company, he'd want to do anything to impress you, too. Why don't you call him and have him come here?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "既然是新來的，那應該很好使喚吧？要趁這個機會找他出來，跟他告白嗎？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ถ้าเขาเพิ่งมาเข้าบริษัท เขาก็คงอยากทำทุกอย่างให้คุณประทับใจเหมือนกันนะคะ ทำไมไม่โทรหาเขาแล้วชวนมาที่นี่ละคะ?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Nếu anh ấy mới đến công ty của cô, anh ấy sẽ muốn làm mọi thứ để gây ấn tượng cho cô. Tại sao cô không gọi anh ta và mời anh ta qua đây?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "如果是新人的话，叫过来应该不难吧。不如直接告白怎么样？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wenn der Counter neu bei euch ist, dann soll er doch vorbeikommen, damit du ihm deine Gefühle zeigen kannst!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Si elle est nouvelle, ça ne devrait pas être trop dur de lui parler, si ? Pourquoi ne pas lui avouer votre flamme directement ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
