L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3800207
L37_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "그럼 다른 사람은 어때? <color=#ffd34c>회사 사람들</color>이라며?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "じゃあ、他の人はどう？　<color=#ffd34c>会社の人</color>程度でいいのよね？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Then, who else? You said <color=#ffd34c>coworkers</color>."
L37_1.m_Talk_ENG = L38_1
L38_1 = "那其他人呢？公司應該還有<color=#ffd34c>其他人</color>吧？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "งั้นมีใครอีกนะคะ? คุณว่า<color=#ffd34c>พวกเพื่อนร่วมงาน</color>นี่นา"
L37_1.m_Talk_THA = L38_1
L38_1 = "Vậy thì là ai? Cô đã nói <color=#ffd34c>đồng nghiệp</color> cơ mà."
L37_1.m_Talk_VTN = L38_1
L38_1 = "那还有别人吗？不是说<color=#ffd34c>公司的同事们</color>吗？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Wen gibt es sonst noch? Du hast von <color=#ffd34c>Kollegen</color> gesprochen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Bon. Tes <color=#ffd34c>collègues</color>, tu dis ? Donne-moi un autre exemple."
L37_1.m_Talk_FRA = L38_1
