L39_1 = "GREMORY_ACT2_EPILOGUE@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3800207
L38_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_SERIOUS2"
L38_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "으음… 저희 부사장님은 항상 냉철하고 자기 일에 열정적이세요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "えっと……副社長は常に落ち着いていて、自分の仕事に情熱的です。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Mm... My vice president is extremely rational and passionate about work."
L38_1.m_Talk_ENG = L39_1
L39_1 = "嗯…副總個性非常冷靜，只熱衷於自己的事。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "อืม... รองประธานของฉันทั้งมีเหตุผลแล้วก็บ้างานสุดๆ ไปเลยค่ะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Mm... Phó chủ tịch của tôi cực kỳ lý trí và đam mê công việc."
L38_1.m_Talk_VTN = L39_1
L39_1 = "嗯……我们的副总经常冷着脸，只热衷于自己的工作。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Mm ... Unser Vizevorsitzender ist äußerst rational und leidenschaftlich bei der Arbeit."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Hum. La vice-présidente est passionnée par son travail, c'est un véritable modèle d'intransigeance."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "GREMORY_ACT2_EPILOGUE@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3800207
L39_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L39_1.m_Pos = "C"
L40_1 = "강하고 책임감이 넘치시는 분이라 아직도 혼자 지내신다는 게 이해가 안 될 정도로요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "強くて責任感が溢れる方なので、まだ独身というのが理解できないくらいです。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I don't understand why such a strong, responsible person is still single."
L39_1.m_Talk_ENG = L40_1
L40_1 = "她也是能力很好，而且非常有責任感，我也覺得很奇怪，為什麼她到現在都是孤家寡人？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ไม่เห็นเข้าใจเลยว่าทำไมคนที่ทั้งแข็งแแกร่งและมีความรับผิดชอบเบอร์นั้นยังโสดอยู่"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tôi không hiểu tại sao một người mạnh mẽ, có trách nhiệm như vậy mà vẫn độc thân."
L39_1.m_Talk_VTN = L40_1
L40_1 = "是位强大又富有责任心的人，我不能理解这样的人为什么还是单身。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ich verstehe nicht, warum eine so starke, verantwortungsbewusste Person immer noch Single ist."
L39_1.m_Talk_DEU = L40_1
L40_1 = "À vrai dire, je ne comprends pas comment quelqu'un d'aussi fort et d'aussi responsable soit encore célibataire."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "GREMORY_ACT2_EPILOGUE@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3800207
L40_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_Face = "UNIT_PRIDE"
L40_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L40_1.m_Pos = "C"
L41_1 = "아아, 좋지~ 한 회사의 부사장이 쿨한 능력남이라면 안 끌리는 게 이상하지."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ああ、いいわね～。一企業の副社長がクールで仕事もできちゃうなら惹かれて当然だわ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Ah, sure. It'd be strange if you weren't attracted to someone so powerful and confident."
L40_1.m_Talk_ENG = L41_1
L41_1 = "哇喔～很棒～身為一家公司的副總，想必是位高富帥吧！怎麼可能不愛上他！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "แหม แน่ล่ะ ถ้าคุณไม่สนใจคนที่ทั้งเก่งทั้งมั่นมันก็คงจะแปลกอยู่นะคะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "À, chắc chắn rồi. Nếu cô không bị ai đó mạnh mẽ và tự tin thu hút, cái đó mới lạ."
L40_1.m_Talk_VTN = L41_1
L41_1 = "啊啊，很好~如果公司的副总是个帅气又有能力的男人，不被他吸引才奇怪吧。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ach, absolut verständlich. Es wäre seltsam, wenn du dich nicht zu jemandem hingezogen fühlen würdest, der so mächtig und selbstbewusst ist."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Oh, autorité et confiance en soi ? Je comprends ton attirance."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "GREMORY_ACT2_EPILOGUE@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3800207
L41_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_IDLE"
L41_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L41_1.m_Pos = "C"
L42_1 = "그 정도면 어느 정도 나이 차는 극복할 수 있겠는데? 한 번쯤 덤벼볼 만하지 않아?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "その感じなら、ある程度の年の差は克服できそうだけど？\n一度くらい狙ってみるべきじゃない？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I don't know how old he is, but it doesn't seem like age difference matters. Why don't you feel him out?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "俗話說年齡不是距離，要勇敢愛一次嗎？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ฉันไม่รู้นะคะว่าเขาอายุเท่าไหร่ แต่เขาคงแก่กว่าคุณแน่เลย ทำไมไม่ลองถามดูละคะว่าเขาคิดยังไง?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi không biết anh ta bao nhiêu tuổi, nhưng anh ta không thể hơn tuổi cô nhiều lắm. Tại sao cô không hỏi thẳng cảm xúc của anh ta?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "如果是这样，就算年龄有点差距也能克服吧？要不要试一试？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ich weiß nicht, wie alt der Vizevorsitzende ist, aber der Altersunterschied ist doch überbrückbar. Warum traust du dich nicht einfach?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "La différence d'âge n'a pas l'air de te gêner, alors pourquoi ne pas tenter ta chance ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "GREMORY_ACT2_EPILOGUE@92#Talk"
