L42_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_SURPRISE"
L42_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = "m_Crash"
L42_1[L43_1] = 20
L43_1 = "그, 그렇게 나이차가 나진 않아요! 하지만 역시 성별에 문제가 있어서…!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "そ、そこまで年の差はありません！　でもやっぱり性別の壁があって……！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "N-not that much older than me, but again, she's a woman..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "呃…我們年紀是沒有差很多啦！只是一樣有性別的問題…！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "มะ-ไม่ได้แก่กว่าฉันนักหรอกค่ะ แล้วก็ เธอเป็นผู้หญิงอีกแล้ว..."
L42_1.m_Talk_THA = L43_1
L43_1 = "K-không lớn hơn tôi bao nhiêu tuổi, nhưng một lần nữa, đó là vấn đề về giới tính..."
L42_1.m_Talk_VTN = L43_1
L43_1 = "年、年龄也不是差很多！不过还是性别的问题……！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "D-der Altersunterschied ist nicht so groß, aber auch sie ist eine Frau ..."
L42_1.m_Talk_DEU = L43_1
L43_1 = "E-Elle n'est pas si âgée, vous savez ? Mais encore une fois, c'est une femme..."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "GREMORY_ACT2_EPILOGUE@93#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 93
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3800207
L43_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_Face = "UNIT_LAUGH"
L43_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L43_1.m_Pos = "C"
L44_1 = "아쉽네. 하지만 내가 남의 취향을 강요할 순 없으니까."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "それは残念ね。でもアタシが人の好みを強要することはできないから。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "What a shame! But I get that isn't your thing."
L43_1.m_Talk_ENG = L44_1
L44_1 = "真可惜～不過我也無法強迫你改變想法。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "น่าเสียดายจัง! แต่ฉันเข้าใจะนะคะที่คุณไม่เป็นตัวของตัวเองน่ะ!"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tiếc quá! Nhưng tôi nghĩ rằng cô chưa hiểu rõ mình."
L43_1.m_Talk_VTN = L44_1
L44_1 = "太可惜啦。但又不能强迫别人改变取向。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Schade! Aber ich verstehe schon, wenn das nicht dein Ding ist."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Dommage. Enfin si ce n'est pas ton truc, on n'y peut rien."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "GREMORY_ACT2_EPILOGUE@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3800207
L44_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L44_1.m_bWaitClick = true
