L44_1.m_Face = "UNIT_IDLE"
L44_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "그럼 여자가 아닌 이상형은 회사에 없는 거야?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "じゃあ、女性じゃない理想の人は会社にいないの？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Isn't there anyone in your company that's not female?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "所以你公司裡都沒有非女性的理想對象嗎？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "มีใครในบริษัทคุณไม่เป็นผู้หญิงบ้างมั้ยคะ?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Không có ai trong công ty của cô không phải là nữ, đúng chứ?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "那么公司里没有除了女性以外的理想型吗？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Gibt es in eurem Unternehmen niemanden, der nicht weiblich ist?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "N'y a-t-il que des femmes, dans ton entreprise ?"
L44_1.m_Talk_FRA = L45_1
