L47_1 = "저희 사장님이요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "うちの社長です。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "My boss."
L46_1.m_Talk_ENG = L47_1
L47_1 = "就我們老闆吧。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "บอสฉันค่ะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ông chủ của tôi."
L46_1.m_Talk_VTN = L47_1
L47_1 = "我们的老板。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Mein Chef."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Il y a bien notre président..."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "GREMORY_ACT2_EPILOGUE@97#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3800207
L47_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L47_1.m_Pos = "C"
L48_1 = "사장님은 저를 포함해서 모든 사원분들에게 무척 친절한 분이세요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "社長は私を含めて、すべての社員にとても親切な方です。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "He's kind to everyone in the company, including me."
L47_1.m_Talk_ENG = L48_1
L48_1 = "老闆對每位員工都非常地親切。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เขาใจดีกับทุกคนในบริษัท รวมทั้งฉันด้วย"
L47_1.m_Talk_THA = L48_1
L48_1 = "Anh ấy tốt với mọi người trong công ty, kể cả tôi."
L47_1.m_Talk_VTN = L48_1
L48_1 = "老板对包括我在内的所有职员们都很亲切。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Er ist nett zu allen in der Firma, einschließlich mir."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Il est gentil avec tout le monde, moi comprise."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "GREMORY_ACT2_EPILOGUE@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3800207
L48_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L48_1.m_Pos = "C"
L49_1 = "가끔 자기를 본 딴 동상에 집착하는 엉뚱한 면을 보이긴 하지만, 그런 면이 오히려 귀엽달까… "
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "たまにご自身がモデルの銅像に執着する突拍子もない面も見せるけど、\nそういうところがむしろ可愛いというか……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Sometimes, he's a bit eccentric of being obsessed with his statues that look like himself, but I find that's cute...  "
L48_1.m_Talk_ENG = L49_1
L49_1 = "雖然有時候對他的等身銅像，有莫名的堅持，不過這樣好像也滿可愛的… "
L48_1.m_Talk_TWN = L49_1
L49_1 = "เขาหมกมุ่นกับรูปปั้นตัวเอง แต่ฉันว่าน่ารักดีค่ะ..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Anh ấy bị ám ảnh bởi những bức tượng của chính mình, nhưng tôi thấy việc ấy thật đáng yêu..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "虽然偶尔会表现出对以自己为造型的金属雕像很执着的样子，但这样反而有些可爱…… "
L48_1.m_Talk_SCN = L49_1
L49_1 = "Manchmal ist er ein bisschen exzentrisch, wenn er von seinen Statuen besessen ist, die wie er selbst aussehen, aber ich finde das süß ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Il a un petit côté excentrique et il est un peu trop obsédé par les statues de lui mais moi, je trouve ça plutôt mignon..."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "GREMORY_ACT2_EPILOGUE@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3800207
L49_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L49_1.m_Pos = "C"
L50_1 = "그런 대하기 편한 성격 덕분에 사원들이 따르는 것 같기도 하구우…"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "そんな接しやすい性格のおかげで社員たちが慕っているような気もするしぃ……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Also, he's not authoritative, which makes him popular among his employees..."
L49_1.m_Talk_ENG = L50_1
L50_1 = "因為他不會讓人有距離感，所以員工們也都很願意替他效勞…"
L49_1.m_Talk_TWN = L50_1
L50_1 = "แถมเขาไม่บ้าอำนาจด้วย พนักงานเลยชอบเขากันทั้งนั้น..."
L49_1.m_Talk_THA = L50_1
L50_1 = "Ngoài ra, anh ấy không hề hống hách, điều này khiến các nhân viên cực kỳ quý mến anh ấy..."
L49_1.m_Talk_VTN = L50_1
L50_1 = "因为有这样温柔的性格，感觉职员们都很喜欢他……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Außerdem ist er nicht autoritär, was ihn bei seinen Mitarbeitern beliebt macht ..."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Et puis il n'abuse jamais de son autorité, ce qui lui vaut sans doute son charisme..."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "GREMORY_ACT2_EPILOGUE@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3800207
L50_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
