L50_1.m_Pos = "C"
L51_1 = "m_Crash"
L50_1[L51_1] = 20
L51_1 = "으으… 제가 취하긴 한 모양이네요. 이런 얘긴 아무한테도 한 적이 없는데…"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "むう……だいぶ酔ってきたようです。こんな話は誰にもしたことがないのに……"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Aww, I really must be drunk. I've never told anyone this before..."
L50_1.m_Talk_ENG = L51_1
L51_1 = "呃…我好像喝醉了，這些話我從來沒對其他人說過…"
L50_1.m_Talk_TWN = L51_1
L51_1 = "โอย ฉันต้องเมาแล้วแน่ๆ เลยค่ะ เรื่องนี้ฉันไม่เคยบอกใครเลยนะคะ..."
L50_1.m_Talk_THA = L51_1
L51_1 = "Aww, tôi thực sự xỉn lắm rồi. Tôi chưa bao giờ nói với ai điều này trước đây cả..."
L50_1.m_Talk_VTN = L51_1
L51_1 = "额额……看来是我喝醉了。这种话我从来没对别人说过……"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Uff, ich muss wirklich betrunken sein. Ich habe das noch nie jemandem erzählt ..."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Oulà, je dois vraiment être ivre. Je n'ai jamais dit ça à personne avant..."
L50_1.m_Talk_FRA = L51_1
