L2_1 = "그 사장님을 나에게 빼앗긴다면 어떤 기분일 것 같아?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "その社長をアタシに奪われたらどんな気分になると思う？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "How would you feel if I stole him from you?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "我把老闆搶過來的話，你會作何感想？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ถ้าฉันไปฉกเขามาคุณจะรู้สึกยังไงคะ?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Cô thấy sao nếu tôi đánh cắp anh ấy khỏi cô?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "如果那位老板被我抢走，你的心情会怎么样呢？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Wie würdest du dich fühlen, wenn ich ihn mir anlachen würde?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Comment te sentirais-tu si je te le volais, ce président ?"
