L5_1 = "사장님은 여자는 아니지만 로봇이시거든요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "社長は女性ではないけど、ロボットなんです。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "The Boss is not a woman, but he's a robot."
L4_1.m_Talk_ENG = L5_1
L5_1 = "我的意思是，雖然老闆不是女生，但他是機器人！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "บอสไม่ใช่ผู้ชายค่ะ แต่เป็นหุ่นยนต์"
L4_1.m_Talk_THA = L5_1
L5_1 = "Boss không phải là phụ nữ, mà là một robot."
L4_1.m_Talk_VTN = L5_1
L5_1 = "老板虽然不是女性，但却是机器人。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Mein Boss ist zwar keine Frau, aber ein Roboter."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Le directeur n'est pas une femme, mais c'est un robot."
L4_1.m_Talk_FRA = L5_1
