L6_1 = "GREMORY_ACT2_EPILOGUE@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3800207
L5_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L5_1.m_Pos = "C"
L6_1 = "생리적인 거부감을 떠나 애초에 사람이 아니라 그런 말씀하셔도 소용없어요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "生理的な抵抗感はさておき、そもそも人間ではないので、そんなことを言っても無駄ですよ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I'm not interested in women, but I'm not interested in robots, either."
L5_1.m_Talk_ENG = L6_1
L6_1 = "排除生理方面的問題，他本來就不算是人類，所以不在討論範圍內啦～"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ฉันไม่ชอบผู้หญิง แต่ก็ไม่ชอบหุ่นยนต์ด้วยค่ะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tôi không thích phụ nữ, nhưng tôi cũng không quan tâm đến người máy."
L5_1.m_Talk_VTN = L6_1
L6_1 = "就算我没有生理上的抗拒感，但因为本来就不是真人，所以说这些都没有意义啦。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ich interessiere mich nicht für Frauen, aber ich interessiere mich auch nicht für Roboter."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Et je ne m'intéresse pas plus aux robots que je ne m'intéresse aux femmes..."
L5_1.m_Talk_FRA = L6_1
