L8_1 = "하지만 하나 씨 눈동자에 비치는 사장님은 로봇이 아닌 것 같은데?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "でもスズカちゃんの瞳に映る社長はロボットじゃないみたいだけど？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "But I don't think the image reflected in your eyes is that of a robot."
L7_1.m_Talk_ENG = L8_1
L8_1 = "可是荷娜，你的眼睛背叛了你的心，我在你眼裡看到的老闆不是機器人啊？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แต่ภาพที่ฉันเห็นจากในดวงตาคุณนี่ไม่ใช่หุ่นยนต์เลยนะคะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Nhưng tôi không nghĩ hình ảnh phản chiếu trong mắt cô là hình ảnh một robot."
L7_1.m_Talk_VTN = L8_1
L8_1 = "但千夜眼中的老板好像不是机器人啊？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Aber ich glaube nicht, dass das Bild, das sich in deinen Augen widerspiegelt, das eines Roboters ist."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Pourtant, j'ai l'impression que ce n'est pas simplement ce que tu vois en lui."
L7_1.m_Talk_FRA = L8_1
