L17_1 = "정말로 내가 하나 씨 눈동자에서 뭘 봤다고 생각한 거야?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "本当にアタシがスズカちゃんの瞳から何か見たとでも思ったの？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Did you really think I saw something through your eyes?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "你真的以為我能從你的眼睛裡看到東西嗎？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "คิดว่าฉันเห็นอะไรจากในดวงตาคุณจริงๆ เหรอคะ?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Cô thực sự nghĩ rằng tôi đã thấy thứ gì đó trong mắt cô sao?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "你真的以为我在你眼里看到了什么吗？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Hast du echt geglaubt, dass ich etwas durch deine Augen sehe?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Tu pensais vraiment que j'avais lu quelque chose dans ton regard ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
