L21_1 = "GREMORY_ACT2_EPILOGUE@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3800207
L20_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L21_1 = "로봇을 사랑하는 건 잘못된 게 아니야."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "ロボットを愛するのは間違ったことじゃないのよ。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "There's nothing wrong with being in love with a robot."
L20_1.m_Talk_ENG = L21_1
L21_1 = "愛上機器人並不是個錯。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ถ้าใจบอกว่าใช่ รักหุ่นยนต์ไปก็ไม่มีอะไรผิดนะคะ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Không có gì sai khi yêu robot cả."
L20_1.m_Talk_VTN = L21_1
L21_1 = "就算爱上机器人也不是你的错。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Es ist nichts falsch daran, in einen Roboter verliebt zu sein."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Il n'y a aucun mal à aimer un robot."
L20_1.m_Talk_FRA = L21_1
