L23_1 = "GREMORY_ACT2_EPILOGUE@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3800207
L22_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_LAUGH"
L22_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = "난 말이지. 사람처럼 생각하고 사람처럼 말한다면 무엇이든 사랑에 빠질 수 있다고 생각해."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "アタシはね、人のように考えて人のように話せるなら、\n誰であれ恋に落ちることはあると思うの。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I think people can fall in love with anything that can think and speak like a human."
L22_1.m_Talk_ENG = L23_1
L23_1 = "我個人認為，只要那個對象可以像人一般思考，像人一般說話，就可以和他談感情。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ฉันว่าคนเรารู้สึกผูกพันกับอะไรก็ตกหลุมรักสิ่งนั้นได้นะคะ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tôi nghĩ mọi người có thể yêu bất cứ thứ gì mà họ có thể kết nối được."
L22_1.m_Talk_VTN = L23_1
L23_1 = "我认为，如果能像人类一样思考，像人类一样说话，不管对方是什么都可以和他一起坠入爱河。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich finde, Menschen können sich in alles verlieben, was denken und sprechen kann wie ein Mensch."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Je pense que nous pouvons tomber amoureux de n'importe qui, tant que cette personne peut penser et parler comme un humain."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "GREMORY_ACT2_EPILOGUE@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3800207
L23_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "하나 양이 진짜 사랑을 만나지 못하고 있는 건, 이미 그 로봇 사장님을 사람과 다름없는 존재라 믿고 있기 때문인 거야."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "スズカちゃんが本当の愛に巡り合えないのは、\nすでにそのロボットの社長を人と変わらない存在だと信じているからなのよ。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "You haven't found someone because, in your mind, you're convinced that this robot boss is a man."
L23_1.m_Talk_ENG = L24_1
L24_1 = "你無法和其他人談戀愛的真正原因，是因為你相信，那個機器人老闆跟人沒有兩樣。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ที่คุณยังไม่เจอคนที่ใช่ เพราะใจคุณเชื่อว่าบอสหุ่นยนต์นั่นเป็นผู้ชายคนหนึ่งไงคะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Cô chưa tìm thấy ai vì trong tâm trí cô, cô tin rằng ông chủ robot này là một người đàn ông."
L23_1.m_Talk_VTN = L24_1
L24_1 = "千夜小姐觉得自己没能遇到真爱，是因为已经深信那个机器人老板是和人类没有区别的存在。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Du hast niemanden gefunden, weil du in Gedanken davon überzeugt bist, dass dein Roboter-Boss ein Mensch ist."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Je crois que si tu es encore célibataire... c'est parce qu'au fond de toi, tu es convaincue que ce robot n'est pas différent d'un homme."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
