L27_1 = "GREMORY_ACT2_EPILOGUE@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3800207
L26_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_LAUGH"
L26_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "m_Crash"
L28_1 = 30
L26_1[L27_1] = L28_1
L27_1 = "여, 역시 그런 걸까요?! 하하…"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "や、やっぱりそうなんでしょうかね！　はは……"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Y-you think so? Hah hah..."
L26_1.m_Talk_ENG = L27_1
L27_1 = "是…是這樣喔？！哈哈…"
L26_1.m_Talk_TWN = L27_1
L27_1 = "คะ-คุณว่าอย่างนั้นเหรอคะ? ฮ่าฮ่า..."
L26_1.m_Talk_THA = L27_1
L27_1 = "C-cô nghĩ vậy không? Ha ha..."
L26_1.m_Talk_VTN = L27_1
L27_1 = "果、果真是这样吧？！哈哈……"
L26_1.m_Talk_SCN = L27_1
L27_1 = "M-meinst du? Haha ..."
L26_1.m_Talk_DEU = L27_1
L27_1 = "V-Vous croyez ? Ha ha..."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "GREMORY_ACT2_EPILOGUE@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3800207
L27_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "m_Crash"
L27_1[L28_1] = 20
L28_1 = "아아… 이제 알겠다… 전 로봇을 <color=#ffd34c>사람이라 생각하고</color> 좋아하고 있었던 거네요? 그렇죠?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ああ……そういうことだったんですね……\n私はロボットを<color=#ffd34c>人だと思って</color>好きになったんですね？　そうでしょう？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Ah... I get it. So, I've unconsciously <color=#ffd34c>convinced myself that the robot is a man</color> and like him, right?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "喔喔…原來是這樣…我好像把機器人<color=#ffd34c>當人</color>，而且還喜歡他對吧？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "อ๊ะ... ฉันเข้าใจแล้วค่ะ คือ ฉัน<color=#ffd34c>เชื่อว่าบอสหุ่นยนต์นั่นเป็นผู้ชายคนหนึ่ง</color>ไปโดยไม่รู้ตัวสินะคะ?"
L27_1.m_Talk_THA = L28_1
L28_1 = "À ... tôi hiểu rồi. Vì vậy, tôi đã vô thức <color=#ffd34c>thuyết phục bản thân rằng ông chủ robot là một người đàn ông</color>, phải không?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "啊啊……我现在懂了……我是将机器人<color=#ffd34c>当作人类</color>，还喜欢上了他？对吧？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ah ... ich verstehe. Also <color=#ffd34c>halte ich den Roboter für einen Menschen</color> und habe mich verknallt, richtig?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ah... Je vois. En fait, je me suis inconsciemment persuadée que <color=#ffd34c>ce robot était un homme</color> pour pouvoir l'aimer, c'est ce que vous dites ?"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "GREMORY_ACT2_EPILOGUE@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3800207
L28_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_LAUGH"
L28_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L28_1.m_Pos = "C"
L29_1 = "그럼~ 기회가 된다면 그 사장님에게 하나 양의 진솔한 마음을 털어놔 봐."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "そうよ～。機会があれば、その社長にスズカちゃんの率直な気持ちを打ち明けてみてね。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Yes. If you have a chance, you should tell him how you really feel about him."
L28_1.m_Talk_ENG = L29_1
L29_1 = "那有機會的話～就把你的心意老實地告訴老闆吧！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ค่ะ ถ้ามีโอกาส ก็ควรบอกเขาไปนะคะว่ารู้สึกยังไง"
L28_1.m_Talk_THA = L29_1
L29_1 = "Đúng. Nếu có cơ hội, cô nên cho anh ấy biết cảm xúc của cô về anh ấy."
L28_1.m_Talk_VTN = L29_1
L29_1 = "那么~如果有机会的话，不如向那个老板吐露千夜小姐真实的内心吧。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ja. Wenn du die Möglichkeit hast, solltest du ihm sagen, was du wirklich für ihn empfindest."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Oui. Si tu trouves l'occasion, je pense que tu devrais lui dire ce que tu ressens pour lui."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
