L29_1.m_Face = "UNIT_IDLE"
L29_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L29_1.m_Pos = "C"
L30_1 = "그리고 좋은 소식 있으면 나한테도 알려줘. 알았지?"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "そして良い報告があればアタシにも教えてね。わかった？"
L29_1.m_Talk_JPN = L30_1
L30_1 = "And let me know how it goes. Okay?"
L29_1.m_Talk_ENG = L30_1
L30_1 = "有好消息的話，記得要告訴我喔！說定囉？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "แล้วมาบอกฉันด้วยนะคะว่าผลเป็นยังไง โอเค้?"
L29_1.m_Talk_THA = L30_1
L30_1 = "Và hãy cho tôi biết kết quả nhé. Được không?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "还有如果有好消息，也可以来告诉我。可以吗？"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Und lass mich wissen, wie es ausging. In Ordnung?"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Et reviens nous raconter comment ça s'est passé, d'accord ?"
L29_1.m_Talk_FRA = L30_1
