L32_1.m_Bounce = L33_1
L33_1 = "영업 끝! 고생하셨습니다!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "営業終了！　お疲れ様でした！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Wrap-up time! Good job, everyone!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "打烊！大家辛苦囉！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "จบปิ้ง! ทุกคนเก่งมากค่า!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Hết giờ rồi!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "营业结束！辛苦了！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Feierabend! Gute Arbeit, alle miteinander!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Allez, on ferme ! Bon travail, tout le monde !"
L32_1.m_Talk_FRA = L33_1
