L33_1.m_Pos = "C"
L34_1 = "후우, 오늘 장사도 참 고됐네."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ふぅ、今日の商売も大変だったわね。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Whew, it was a tough day as usual."
L33_1.m_Talk_ENG = L34_1
L34_1 = "呼～今天也好累喔～"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เฮ้อ หนักกว่าปกตินะวันนี้"
L33_1.m_Talk_THA = L34_1
L34_1 = "Chà, một ngày khó khăn như thường lệ."
L33_1.m_Talk_VTN = L34_1
L34_1 = "呼，今天的工作真辛苦。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Puh, es war wie immer ein harter Tag."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Pfiouh. Aujourd'hui encore, les affaires ont bien marché."
L33_1.m_Talk_FRA = L34_1
