L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3800207
L36_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
