L38_1 = 30
L36_1[L37_1] = L38_1
L37_1 = "역시 굉장하네요, 그레모리 씨!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "やっぱりすごいです、グレモリーさんは！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "You're incredible, Gremory!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "真不愧是葛茉莉，超強的！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "คุณเก่งเหลือเชื่อเลยค่ะเกรมอรี!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Chị thật tuyệt vời, Gremory!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "果然很厉害呢，葛茉莉小姐！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Du bist unglaublich, Gremory!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Vous êtes vraiment incroyable, Gremory !"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "GREMORY_ACT2_EPILOGUE@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3800207
L37_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L37_1.m_Pos = "L"
L38_1 = "몇 마디 나누는 것만으로 하나 씨의 고민을 완벽하게 해결해 주셨잖아요!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "少し話しただけでスズカさんの悩みを完璧に解決してあげましたね！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "You perfectly solved Hana's problem just by talking to her for a while."
L37_1.m_Talk_ENG = L38_1
L38_1 = "不過幾句話就完美地解開荷娜的煩惱！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แค่คุยกับฮานาแป๊บเดียวก็แก้ปัญหาให้เธอได้อย่างสมบูรณ์แบบแล้ว"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chị đã giải quyết vấn đề của Hana một cách hoàn hảo chỉ bằng cách nói chuyện với cô ấy trong một chút thời gian."
L37_1.m_Talk_VTN = L38_1
L38_1 = "轻松几句话就完美解决了千夜小姐的烦恼！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Du hast Hanas Problem perfekt gelöst, indem du einfach eine Weile mit ihr geredet hast."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Vous avez réussi à résoudre le problème d'Hana juste en l'écoutant parler un court instant !"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "GREMORY_ACT2_EPILOGUE@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3800207
L38_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L38_1.m_Pos = "R"
L39_1 = "내가 그랬나?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "そうだったっけ？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Did I?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "我有嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ใช่เหรอ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Vậy sao?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "我有吗？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Habe ich das?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "J'ai fait ça, moi ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "GREMORY_ACT2_EPILOGUE@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3800207
L39_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_PRIDE"
L39_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L39_1.m_Pos = "L"
L40_1 = "그럼요! 상담에 얼마나 감명을 받았으면 밤새도록 칵테일을 아홉 잔이나 주문하셨겠어요?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "そうですよ！　相談内容に相当感動したのか、\n一晩でカクテルを9杯も注文したんですよ？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Absolutely! You made her so happy that she ordered nine cocktails in a row!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "有啊！要是沒效的話，她怎麼會整個晚上點了九杯雞尾酒？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ใช่สิคะ! คุณทำเธอแฮปปี้จนสั่งค็อกเทลเก้าแก้วรวดเลยค่ะ!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Chắc chắn rồi! Chị đã làm cô ấy vui vẻ đến nỗi gọi liên tiếp 9 ly cocktail!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "当然！如果不是烦恼得到了解决，千夜小姐也不会一整晚连点九杯鸡尾酒吧？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Absolut! Du hast sie so glücklich gemacht, dass sie neun Cocktails hintereinander bestellt hat!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Absolument ! Vous l'avez rendue si heureuse qu'elle a commandé neuf cocktails d'affilée !"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "GREMORY_ACT2_EPILOGUE@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3800207
L40_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_Face = "UNIT_DESPAIR"
L40_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L40_1.m_Pos = "L"
L41_1 = "하나 씨한테 말을 걸었던 손님들이 전부 어린아이처럼 울면서 도망가긴 했지만…"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "スズカさんに声をかけたお客様たちは、\nみんな子どものように泣きながら逃げていったけど……"
L40_1.m_Talk_JPN = L41_1
L41_1 = "And she made all the customers who tried to talk to her run away crying..."
L40_1.m_Talk_ENG = L41_1
L41_1 = "雖然向荷娜搭訕的客人，最後都哭得像孩子一樣奪門而出…"
L40_1.m_Talk_TWN = L41_1
L41_1 = "แถมเธอทำให้ลูกค้าทุกคนที่พยายามคุยกับเธอร้องไห้วิ่งหนีไปหมดด้วย..."
L40_1.m_Talk_THA = L41_1
L41_1 = "Và cô ấy đã khiến tất cả những khách hàng cố gắng nói chuyện với cô ấy phải bỏ chạy và khóc lóc..."
L40_1.m_Talk_VTN = L41_1
L41_1 = "虽然向她搭讪的顾客们全都像小孩子一样哭着跑开了……"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Und sie brachte alle Gäste, die versuchten, mit ihr zu plaudern, zum Weinen ..."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Bon, elle a fait fuir tous les clients qui essayaient de lui parler en pleurant..."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "GREMORY_ACT2_EPILOGUE@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3800207
L41_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_LAUGH"
L41_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L41_1.m_Pos = "L"
L42_1 = {}
L43_1 = 2
L44_1 = 0.2
L42_1[1] = L43_1
L42_1[2] = L44_1
L41_1.m_Bounce = L42_1
L42_1 = "…그래도 인명사고는 없었으니까요!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "……でも怪我人はいなかったですし！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Well, at least no one got hurt in the process!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "…不過至少沒有出人命啦！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เอาเถอะ อย่างน้อยก็ไม่มีใครบาดเจ็บนะคะ!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Chà, ít nhất không ai bị thương!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "……至少没有出现人命事故！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "... nun, wenigstens wurde dabei niemand verletzt!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "... Mais au moins, il n'y a eu aucun blessé !"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "GREMORY_ACT2_EPILOGUE@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3800207
L42_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_PRIDE"
L42_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L42_1.m_Pos = "R"
L43_1 = "후훗, 니콜 양의 지금 같은 긍정적인 마인드라면 나처럼 훌륭한 사랑 해결사가 되는 것도 그리 먼 이야기는 아니야."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ふふっ、ニコルちゃんの今のようなポジティブマインドなら、\nアタシのように立派な恋愛カウンセラーになるのもそんなに遠い話じゃないわね。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Hah hah. Nicole, with your optimism, you can become a relationship expert like me in no time."
L42_1.m_Talk_ENG = L43_1
L43_1 = "呵呵～如果你一直都保持這種正面的心態，應該很快就能成為和我一樣優秀的愛情專家吧？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ฮ่าฮ่า เธอนี่มองโลกในแง่ดีจังนิโคล เดี๋ยวเธอก็เป็นผู้เชี่ยวชาญด้านความสัมพันธ์ได้แบบฉันแล้วนะนี่"
L42_1.m_Talk_THA = L43_1
L43_1 = "Ha ha. Nicole, với sự lạc quan của em, em sẽ trở thành một chuyên gia tình yêu như chị nhanh thôi.."
L42_1.m_Talk_VTN = L43_1
L43_1 = "呼呼。如果妮可你保持现在这样积极向上的心态，不需要多久就能成为像我一样优秀的爱情烦恼终结者。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Hahaha. Nicole, mit deinem Optimismus kannst du im Handumdrehen eine Beziehungsexpertin wie ich werden."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Ha ha. Avec un tel optimisme, tu deviendras une experte en problèmes sentimentaux en un rien de temps, Nicole !"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
