L45_1 = 30
L43_1[L44_1] = L45_1
L44_1 = "네! 열심히 하겠습니다!"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "はい！　頑張ります！"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Okay, thanks!"
L43_1.m_Talk_ENG = L44_1
L44_1 = "是！我會努力的！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "โอเคค่ะ ขอบคุณนะคะ!"
L43_1.m_Talk_THA = L44_1
L44_1 = "Được rồi được rồi, cảm ơn chị!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "好！我会努力的！"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Wie nett von dir, danke!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Merci, c'est tout ce que je souhaite !"
L43_1.m_Talk_FRA = L44_1
