L48_1.m_Face = "UNIT_IDLE"
L48_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L48_1.m_Pos = "R"
L49_1 = "아, 잠시만 기다리세요. 가게 뒷정리만 마저 끝내고 책 읽어 줄게요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "あ、少し待ってください。\n店の後片付けだけ終わらせたら絵本を読んであげます。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Oh, give me a moment. Let me finish cleaning the shop. I'll read you some books before bed."
L48_1.m_Talk_ENG = L49_1
L49_1 = "等等再睡，我還要整理一下店裡，整理完再說床邊故事給你聽。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "โอ๊ะ รอแป๊บนะ เดี๋ยวฉันทำความสะอาดร้านแล้วไปอ่านนิทานให้ฟังก่อนนอนนะ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Ồ, chờ tôi một chút. Sau khi dọn quán xong tôi sẽ đọc cho cô vài quyển sách trước khi đi ngủ."
L48_1.m_Talk_VTN = L49_1
L49_1 = "啊，请稍等。我整理好店里的东西，马上就给你读书。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Oh, einen Moment noch. Lass mich den Laden noch fertig putzen. Ich lese dir vor dem Schlafengehen ein paar Bücher vor."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Encore un peu de patience, Momo. Je viens te lire une histoire dès que j'ai fini de ranger le bar."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
