L51_1 = "그 전까지 양치하면서 기다리고 있어요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "それまでに歯磨きして待っててくださいね。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Now, go brush your teeth while waiting for me."
L50_1.m_Talk_ENG = L51_1
L51_1 = "那你先去刷牙等我。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ทีนี้ก็ไปแปรงฟันรอได้เลย"
L50_1.m_Talk_THA = L51_1
L51_1 = "Bây giờ, hãy đi đánh răng trong khi đợi tôi nhé."
L50_1.m_Talk_VTN = L51_1
L51_1 = "那在这之前，你先去刷好牙等我。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Putz dir bis dahin die Zähne."
L50_1.m_Talk_DEU = L51_1
L51_1 = "En attendant, tu peux déjà aller te brosser les dents."
L50_1.m_Talk_FRA = L51_1
