L3_1 = "UNIT_SERIOUS"
L2_1.m_Face = L3_1
L2_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L2_1.m_Pos = "R"
L3_1 = "싫다뇨! 양치 안 하면 충치 악마들이 와서 모모 이를 몽땅 뽑아갈 거라고요!"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "いけません！　歯磨きをしないと虫歯の悪魔が来て、\nモモの歯をぜーんぶ抜いていくんですよ！？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "No? If you don't brush, the bacteria devils will come to pull all your teeth out!"
L2_1.m_Talk_ENG = L3_1
L3_1 = "什麼不要！不刷牙的話，蛀牙怪獸會來把你的牙齒拔光喔！"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ไม่เหรอ? ถ้าไม่แปรงฟันปีศาจแบคทีเรียจะมาถอนฟันไปหมดนะ!"
L2_1.m_Talk_THA = L3_1
L3_1 = "Không? Nếu cô không đánh răng, lũ ác ma vi khuẩn sẽ đến nhổ hết răng đi đấy!"
L2_1.m_Talk_VTN = L3_1
L3_1 = "你要听话！不刷牙的话，会有蛀牙恶魔们来把莫莫的牙齿都拔光的！"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Nein? Wenn du nicht willst, werden die Bakterienteufel kommen, um dir alle Zähne auszureißen!"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Non ? Si tu ne te brosses pas les dents, les bactéries diaboliques viendront te les arracher une par une pendant ton sommeil..."
L2_1.m_Talk_FRA = L3_1
