L3_1.m_Bounce = L4_1
L4_1 = "추, 충치 악마들도 악마니까, 이 몸의 하수인이니라!"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "む、虫歯の悪魔だって悪魔なんだから、吾輩の下僕である！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "B-bacteria devils are also devils, so they are my subjects, too!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "本…本王才不怕蛀牙怪獸！怪獸也是本王的手下！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ปะ-ปีศาจแบคทีเรียก็เป็นปีศาจเหมือนกัน เพราะงั้นก็เป็นบริวารข้าเหมือนกันอ้ะ!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Á-ác ma vi khuẩn cũng là ác ma, nên chúng cũng là thần dân của ta!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "蛀、蛀牙恶魔们也是恶魔，所以都是本尊的仆从！"
L3_1.m_Talk_SCN = L4_1
L4_1 = "B-Bakterienteufel sind auch Teufel, also sind sie auch meine Untertanen!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Les bactéries diaboliques sont aussi des diables, non ? Alors ce sont mes sujets !"
L3_1.m_Talk_FRA = L4_1
