L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L7_1 = "하수인이라도 소용없어요. 악마는 원래 주인 말도 안 듣는 제멋대로인 존재라고요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "下僕でもだめです。\n悪魔はもともと主人の言うことも聞かないわがままな存在なんですよ？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Doesn't matter. Devils don't listen to their masters, anyway."
L6_1.m_Talk_ENG = L7_1
L7_1 = "是你的手下又怎樣？蛀牙怪獸根本不聽主人的話！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ไม่เกี่ยวหรอก ยังไงปีศาจก็ไม่ฟังเจ้านายอยู่แล้วนี่"
L6_1.m_Talk_THA = L7_1
L7_1 = "Chẳng sao. Dù gì thì những con ác ma cũng không nghe lời chủ nhân của chúng đâu."
L6_1.m_Talk_VTN = L7_1
L7_1 = "就算是你的仆从也没用。因为恶魔本来就是不听主人话的存在。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Egal. Teufel hören sowieso nicht auf ihre eigenen Herren."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Peu importe. Les diables n'écoutent jamais ce qu'on leur dit, de toute façon."
L6_1.m_Talk_FRA = L7_1
