L8_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "임금님, 니콜 양 말 안 들으면 이 몽땅 뽑아버린다?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "王様、ニコルちゃんの言うことを聞かないとその歯、全部抜いちゃうよ？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Your Majesty, you'd better listen to Nicole, or I'm going to pull all your teeth out."
L8_1.m_Talk_ENG = L9_1
L9_1 = "國王，你再不聽妮可的話，我要把你牙齒拔光囉？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ฝ่าบาทควรเชื่อฟังนิโคลนะคะ ไม่อย่างนั้นฉันจะถอนฟันให้เอง"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tiểu Điện Hạ, tốt hơn hết là cô nên nghe lời Nicole, nếu không tôi sẽ nhổ hết răng của cô."
L8_1.m_Talk_VTN = L9_1
L9_1 = "小女王陛下，如果不听妮可小姐的话，会被拔掉所有的牙齿哦？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Majestät, du solltest lieber auf Nicole hören, sonst ziehe ich dir alle Zähne."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Majesté, tu ferais mieux de faire ce que Nicole te dit. Sinon, c'est moi qui vais venir t'arracher les dents."
L8_1.m_Talk_FRA = L9_1
