L15_1 = "m_bCharPinup"
L14_1[L15_1] = true
L15_1 = "(일상이 매일 오늘만 같으면 좋겠어요.)"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "(毎日が今日みたいだといいですね。)"
L14_1.m_Talk_JPN = L15_1
L15_1 = "(I wish every day could be like today.)"
L14_1.m_Talk_ENG = L15_1
L15_1 = "(真希望每天都像今天這樣。)"
L14_1.m_Talk_TWN = L15_1
L15_1 = "(อยากให้เป็นแบบนี้ทุกวันเลยนะ)"
L14_1.m_Talk_THA = L15_1
L15_1 = "(Mình ước mỗi ngày đều có thể như ngày hôm nay.)"
L14_1.m_Talk_VTN = L15_1
L15_1 = "（如果每天都能像今天这样就好了。）"
L14_1.m_Talk_SCN = L15_1
L15_1 = "(Ich wünschte, jeder Tag könnte so sein wie heute.)"
L14_1.m_Talk_DEU = L15_1
L15_1 = "(J'aimerais que les jours comme celui-ci ne se terminent jamais.)"
L14_1.m_Talk_FRA = L15_1
