L16_1 = "(不過…這種生活不可能一直持續下去的吧？)"
L15_1.m_Talk_TWN = L16_1
L16_1 = "(แต่... ฉันอยู่แบบนี้ไปตลอดไม่ได้หรอก)"
L15_1.m_Talk_THA = L16_1
L16_1 = "(Nhưng ... mình không thể cứ thế này mãi.)"
L15_1.m_Talk_VTN = L16_1
L16_1 = "（但是……应该不能一直像现在这样吧。）"
L15_1.m_Talk_SCN = L16_1
L16_1 = "(Aber ... es kann nicht ewig so bleiben.)"
L15_1.m_Talk_DEU = L16_1
L16_1 = "(Mais... tout cela ne peut pas durer éternellement.)"
L15_1.m_Talk_FRA = L16_1
