L27_1 = "GREMORY_ACT2_EPILOGUE@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3800207
L26_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "지난번에 니콜에게 상담받았던 손님. 덕분에 애인이랑 잘 해결됐다나 봐."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "この前ニコルちゃんに相談していたお客さんがね、\nおかげで恋人とうまく解決したって。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "The customer you talked to last time. She made up with her boyfriend."
L26_1.m_Talk_ENG = L27_1
L27_1 = "是上次妮可接待的客人送的，好像跟你聊完後感情又死灰復燃。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ลูกค้าที่เธอคุยด้วยคราวก่อนน่ะ ทำตามคำแนะนำของเธอแล้วได้คืนดีกับแฟน"
L26_1.m_Talk_THA = L27_1
L27_1 = "Khách hàng mà em đã nói chuyện lần trước. Cô ấy đã nghe theo lời khuyên của em và làm lành với bạn trai của mình."
L26_1.m_Talk_VTN = L27_1
L27_1 = "上次向你倾诉过烦恼的顾客，好像多亏了你才和爱人和好。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Der Gast, mit dem du letztens gesprochen hast, hat sich mit ihrem Freund versöhnt."
L26_1.m_Talk_DEU = L27_1
L27_1 = "C'est de la part de la cliente de l'autre jour. Grâce à toi, elle s'est réconciliée avec son petit ami."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "GREMORY_ACT2_EPILOGUE@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3800207
L27_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_LAUGH"
L27_1.m_CharStrID = "GREMORY_BAR_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "그래서 이렇게 답례라며 선물을 보내왔어."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "それで、お礼がしたいとこれを贈ってくれたの。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "She sent it to you as a thank-you gift."
L27_1.m_Talk_ENG = L28_1
L28_1 = "所以就寄這個過來，說是要給你的謝禮。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ก็เลยส่งเค้กนี่มาเป็นของขวัญขอบคุณให้เธอ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Cô ấy đã gửi nó cho em làm quà cảm ơn đấy."
L27_1.m_Talk_VTN = L28_1
L28_1 = "所以送来这个当作答谢的礼物。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Sie hat dir das als Dankeschön geschickt."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Alors elle t'a envoyé ce cadeau de remerciement."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
