L32_1 = "GREMORY_ACT2_EPILOGUE@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3800207
L31_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L31_1.m_Pos = "R"
L32_1 = "m_bCharPinup"
L31_1[L32_1] = true
L32_1 = "(비록 성서의 말씀을 빌린 고해성사의 자리는 아니었지만…)"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "(聖書の言葉を引用したゆるしの秘跡ではなかったのですが……)"
L31_1.m_Talk_JPN = L32_1
L32_1 = "(Even though I wasn't in the confessional...)"
L31_1.m_Talk_ENG = L32_1
L32_1 = "(雖然我沒有引經據典…)"
L31_1.m_Talk_TWN = L32_1
L32_1 = "(ถึงฉันจะไม่ได้อยู่ในการสารภาพบาป)"
L31_1.m_Talk_THA = L32_1
L32_1 = "(Mặc dù mình không trong phòng xưng tội...)"
L31_1.m_Talk_VTN = L32_1
L32_1 = "（虽然没有用圣经中的话语劝诫别人……）"
L31_1.m_Talk_SCN = L32_1
L32_1 = "(Obwohl ich nicht im Beichtstuhl war ...)"
L31_1.m_Talk_DEU = L32_1
L32_1 = "(Même sans être au confessionnal...)"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "GREMORY_ACT2_EPILOGUE@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3800207
L32_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L32_1.m_Pos = "R"
L33_1 = "m_bCharPinup"
L32_1[L33_1] = true
L33_1 = "(만화에서 배운 지식을 빌려 바에서 손님들과 대화를 나누는 것만으로 사람들의 고민을 해결해 줄 수 있는 거네요.)"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "(漫画で学んだ知識を活かして、バーでお客様と会話をするだけで\n人々の悩みを解決できるのですね。)"
L32_1.m_Talk_JPN = L33_1
L33_1 = "(I tried to listen to her as best as I could, using the knowledge from the comics I read, and it really helped her.)"
L32_1.m_Talk_ENG = L33_1
L33_1 = "(而是用漫畫裡學到的知識來和客人交談，原來這樣也可以解決人的煩惱。)"
L32_1.m_Talk_TWN = L33_1
L33_1 = "(แต่ฉันก็พยายามตั้งใจฟังเธอ ใช้ความรู้ที่อ่านมาจากในการ์ตูนเต็มที่ แล้วมันก็ช่วยเธอได้จริงๆ)"
L32_1.m_Talk_THA = L33_1
L33_1 = "(Mình đã cố gắng hết sức để lắng nghe cô ấy, bằng kiến thức mà mình đã đọc từ những cuốn truyện tranh, và nó thực sự đã giúp ích cho cô ấy.)"
L32_1.m_Talk_VTN = L33_1
L33_1 = "（但用漫画中学到的知识与顾客们聊天，也能帮助别人解决烦恼。）"
L32_1.m_Talk_SCN = L33_1
L33_1 = "(habe ich versucht, ihr so gut wie möglich zuzuhören, indem ich das Wissen aus den Comics genutzt habe. Und es hat ihr wirklich geholfen.)"
L32_1.m_Talk_DEU = L33_1
L33_1 = "(J'ai écouté du mieux que je pouvais, en mobilisant tout le savoir puisé dans les BD que Gremory m'a montrées. Et ça a marché !)"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "GREMORY_ACT2_EPILOGUE@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3800207
L33_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_PRIDE"
L33_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L33_1.m_Pos = "R"
L34_1 = "m_bCharPinup"
L33_1[L34_1] = true
L34_1 = "(저란 사람은… 언제나 보이는 겉모습에만 너무 연연하고 있었던 걸지도 몰라요.)"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "(私という人間は……\nいつも目に見える外見ばかりに執着しすぎていたのかもしれません。)"
L33_1.m_Talk_JPN = L34_1
L34_1 = "(Maybe, I wonder if I was obsessed with appearances instead of what's underneath...)"
L33_1.m_Talk_ENG = L34_1
L34_1 = "(我之前…或許都太執著於表面看到的東西。)"
L33_1.m_Talk_TWN = L34_1
L34_1 = "(ทีนี้ก็อดสงสัยไม่ได้เลยแฮะว่าฉันหมกมุ่นกับรูปลักษณ์ภายนอกมากกว่าสิ่งที่อยู่ภายในรึเปล่า...)"
L33_1.m_Talk_THA = L34_1
L34_1 = "(Bây giờ, mình băn khoăn không biết liệu mình bị ám ảnh bởi ngoại hình hay những phẩm chất đằng sau nó...)"
L33_1.m_Talk_VTN = L34_1
L34_1 = "（我或许……总是对眼前的表象过于执着。）"
L33_1.m_Talk_SCN = L34_1
L34_1 = "(Vielleicht war ich von Äußerlichkeiten besessen, anstatt von dem, was darunter ist ...)"
L33_1.m_Talk_DEU = L34_1
L34_1 = "(Cette cliente... Elle était si obsédée par les apparences qu'elle ne voyait pas ce qu'il y avait au fond des gens.)"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
