L37_1 = "GREMORY_ACT2_EPILOGUE@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3800207
L36_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L36_1.m_bWaitClick = true
