L36_1.m_Face = "UNIT_LAUGH"
L36_1.m_CharStrID = "MOMO_BAR_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "니콜~ 이 몸도 케이크가 먹고 싶도다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ニコル～吾輩もケーキが食べたいのだ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Nicole, I want to eat your cake, too."
L36_1.m_Talk_ENG = L37_1
L37_1 = "妮可～本王也想吃蛋糕～"
L36_1.m_Talk_TWN = L37_1
L37_1 = "นิโคล ข้าก็อยากกินเค้กด้วยอะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Nicole, ta cũng muốn ăn bánh của cô."
L36_1.m_Talk_VTN = L37_1
L37_1 = "妮可~本尊也想吃蛋糕。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Nicole, ich will auch Kuchen essen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Nicole ! Moi aussi, je veux goûter le gâteau !"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "GREMORY_ACT2_EPILOGUE@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3800207
L37_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "네, 같이 먹어요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "はい、一緒に食べましょう。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Sure, you can have some."
L37_1.m_Talk_ENG = L38_1
L38_1 = "好啊，大家一起吃吧～"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ได้สิ มากินด้วยกัน"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chắc chắn, cô có thể thử chút."
L37_1.m_Talk_VTN = L38_1
L38_1 = "好，那一起吃吧。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Klar, kannst du haben."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Bien sûr, Momo."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "GREMORY_ACT2_EPILOGUE@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3800207
L38_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_IDLE"
L38_1.m_CharStrID = "BARTENDER_BAR_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "대신 먹고 나서 양치 꼭 하는 거예요?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "代わりに、食べた後は必ず歯磨きですよ？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But you'll brush your teeth afterward. Promise?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "不過你吃完一定要刷牙喔？"
