L43_1 = "이 시간이 영원하길 바라진 않아요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "m_bTalkCenterFadeIn"
L42_1[L43_1] = true
L43_1 = "この時間が永遠に続くことを願ってはいません。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I don't expect this to last forever."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我不奢望時間就可以就此暫停。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ฉันก็ไม่หวังหรอกนะคะว่ามันจะเป็นแบบนี้ไปตลอด"
L42_1.m_Talk_THA = L43_1
L43_1 = "Mình không mong điều này kéo dài mãi mãi."
L42_1.m_Talk_VTN = L43_1
L43_1 = "我不奢望现在的时光能够变为永恒。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ich erwarte nicht, dass das ewig so bleibt."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Je sais bien que tout cela ne durera pas éternellement."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "GREMORY_ACT2_EPILOGUE@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3800207
L43_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "후회가 없기를 바라는 것도 욕심이겠죠."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "m_bTalkCenterFadeIn"
L43_1[L44_1] = true
L44_1 = "後悔がないことを願うのも私の欲でしょう。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I'd be greedy if I wanted no regrets, too."
L43_1.m_Talk_ENG = L44_1
L44_1 = "期待沒有後悔也是種奢求。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "และถ้าฉันไม่อยากเสียใจภายหลังก็ดูจะโลภมากไปด้วย"
L43_1.m_Talk_THA = L44_1
L44_1 = "Mình sẽ trở nên tham lam nếu muốn không có gì phải hối tiếc."
L43_1.m_Talk_VTN = L44_1
L44_1 = "亦不希望因渴求完美而招致贪婪。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Es wäre gierig von mir, wenn ich es niemals bereuen will."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Et que j'aurai des regrets, aussi. Ce serait naïf de croire le contraire."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "GREMORY_ACT2_EPILOGUE@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
