L44_1.m_CutScenStrID = "GREMORY_ACT2_EPILOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "다만, 저에게 주어진 이 모든 시간에 그만한 가치가 있기를…"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "m_bTalkCenterFadeIn"
L44_1[L45_1] = true
L45_1 = "ただ、私に与えられたこのすべての時間に、\nそれだけの価値がありますように……"
L44_1.m_Talk_JPN = L45_1
L45_1 = "But I will pray to myself..."
L44_1.m_Talk_ENG = L45_1
L45_1 = "我只希望在我有限的時間內，可以活得有價值…"
L44_1.m_Talk_TWN = L45_1
L45_1 = "แต่ฉันจะภาวนากับตัวเองค่ะ..."
L44_1.m_Talk_THA = L45_1
L45_1 = "Nhưng mình sẽ tự cầu nguyện với chính mình..."
L44_1.m_Talk_VTN = L45_1
L45_1 = "但，我希望赐予我的所有瞬间都有其对应的价值……"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Aber ich werde diesmal zu mir selbst beten ..."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Mais je prierai, pour moi-même..."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
