L45_1.m_fTalkTime = 0.03
L46_1 = "m_bTalkCenterFadeIn"
L45_1[L46_1] = true
L46_1 = "今度は自分自身に祈ります。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "that all the time given to me will be valuable."
L45_1.m_Talk_ENG = L46_1
L46_1 = "這是我對我自己的祈禱。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ว่าจะเห็นคุณค่าของทุกช่วงเวลาที่ตัวเองได้รับ"
L45_1.m_Talk_THA = L46_1
L46_1 = "rằng tất cả thời gian dành cho mình sẽ có giá trị."
L45_1.m_Talk_VTN = L46_1
L46_1 = "这次我要向我自己祈祷。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "dass all die Zeit, die mir gegeben wird, wertvoll sein möge."
L45_1.m_Talk_DEU = L46_1
L46_1 = "...que tous les instants qui me sont accordés soient précieux comme celui-ci."
L45_1.m_Talk_FRA = L46_1
